    const opts = ['<option value="">— no cam —</option>'];
    Object.keys(groups).forEach((g) => {
      opts.push(`<optgroup label="${tlEsc(g)}">` + groups[g].map((s) =>
        `<option value="${tlEsc(s.url)}"${s.url === cur ? ' selected' : ''}>${tlEsc(s.label)}</option>`).join('') + '</optgroup>');
    });
