function getPath(obj, dotted) {
  return dotted.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
}

function buildOnAirGrid() {
  const grid = el('onair-grid');
  if (!grid || grid.dataset.built) return;
  grid.dataset.built = '1';
  // These have full Trigger rows (with options like team/title/player) below — don't duplicate
  // them as bare show/hide toggles up here, which fire without options and look broken.
  const TRIGGER_COVERED = new Set(['break', 'winner', 'intro', 'veto', 'spotlight']);
  ONAIR_SCENES.filter((s) => !TRIGGER_COVERED.has(s.key)).forEach((s) => {
    const card = document.createElement('div');
    card.className = 'onair-card';
    card.id = 'air-card-' + s.key;
    card.innerHTML = `
      <div>
        <div class="oc-label">${s.label}</div>
        <div class="oc-state" id="air-state-${s.key}">HIDDEN</div>
      </div>
      <label class="switch"><input type="checkbox" id="air-${s.key}"><span class="slider"></span></label>`;
    grid.appendChild(card);
    card.querySelector('#air-' + s.key).addEventListener('change', function () {
      send(s.msg, { visible: this.checked });
    });
  });
}

let _sceneFilterGroup = 'all';   // active category chip
let _sceneFilterText = '';       // search box text (lowercased)
let _sceneViewMode = 'grid';     // 'grid' or 'list'

const SCENE_DEFAULT_ASPECT = '1920 × 1080';

// ── Per-scene background wash (colour + opacity %), persisted in localStorage ──
function sceneBgKey(path) { return 'ne_scene_bg_' + path.split('?')[0]; }
function loadSceneBg(path) { try { return JSON.parse(localStorage.getItem(sceneBgKey(path))) || {}; } catch { return {}; } }
function saveSceneBg(path, v) { try { localStorage.setItem(sceneBgKey(path), JSON.stringify(v)); } catch {} }
function sceneBgParams(bg) {
  if (!bg || !bg.on) return '';
  const hex = (bg.color || '#000000').replace('#', '');
  const op = Math.max(1, Math.min(100, bg.op == null ? 50 : bg.op));
  return 'bg=' + hex + '&bgop=' + op;
}
function withParam(url, extra) { return extra ? url + (url.includes('?') ? '&' : '?') + extra : url; }
function prettySceneName(file) {
  return file.replace(/\.html$/i, '').replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

// Merge curated SCENE_SOURCES with overlay HTML found on disk so newly-added scenes
// appear automatically (uncurated files land in an "Other Overlays" group).
function mergeSceneGroups(discovered) {
  const groups = SCENE_SOURCES.map((g) => ({ group: g.group, icon: g.icon, items: g.items.slice() }));
  const curated = new Set();
  groups.forEach((g) => g.items.forEach((it) => curated.add(it.path.split('?')[0].replace(/^\//, '').toLowerCase())));
  const extra = (discovered || []).filter((o) => o.file && !curated.has(o.file.toLowerCase()));
  if (extra.length) {
    groups.push({ group: 'Other Overlays', icon: 'film',
      items: extra.map((o) => ({ name: prettySceneName(o.file), path: o.path, live: null, desc: o.desc || 'Auto-discovered overlay.' })) });
  }
  return groups;
}

// Compact list-view row for a scene — no thumbnail, just name + description + actions.
function buildSceneRow(it, groupName) {
  const base = SCENE_BASE_URL + it.path;
  const row = document.createElement('div');
  row.className = 'scene-row';
  row.dataset.search = (it.name + ' ' + (it.desc || '') + ' ' + groupName).toLowerCase();
  row.dataset.live = it.live || '';
  row.innerHTML = `
    <div class="scene-row-info">
      <div class="scene-row-name">${it.name}</div>
    </div>
    <div class="scene-row-desc">${it.desc || ''}</div>
    <div class="scene-row-acts">
      <button class="btn btn-primary btn-xs sr-open">Open</button>
      <button class="btn btn-ghost btn-xs sr-copy">Copy</button>
      <span class="scene-onair-pill sr-air" hidden>ON AIR</span>
    </div>`;
  row.querySelector('.sr-open').addEventListener('click', () => window.open(base, '_blank'));
  const copyBtn = row.querySelector('.sr-copy');
  copyBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const done = () => { copyBtn.textContent = 'Copied!'; setTimeout(() => { copyBtn.textContent = 'Copy'; }, 1200); };
    if (navigator.clipboard) navigator.clipboard.writeText(base).then(done).catch(() => prompt('Copy URL:', base));
    else prompt('Copy URL:', base);
  });
  return row;
}

// One scene card: thumbnail (+ aspect badge + on-air pill), actions, and a
// per-graphic background-fill settings panel (colour + opacity %, off by default).
function buildSceneCard(it, groupName) {
  const base = SCENE_BASE_URL + it.path;
  const aspect = it.aspect || SCENE_DEFAULT_ASPECT;
  const _am = String(aspect).match(/(\d+)\s*[×x]\s*(\d+)/);
  const nativeW = _am ? +_am[1] : 1920, nativeH = _am ? +_am[2] : 1080;
  let bg = loadSceneBg(it.path);
  const liveUrl  = () => withParam(base, sceneBgParams(bg));
  const fullPrev = () => withParam(base + (base.includes('?') ? '&' : '?') + 'preview=1', sceneBgParams(bg));
  const thumbUrl = () => withParam(base + (base.includes('?') ? '&' : '?') + 'preview=1&thumb=1', sceneBgParams(bg));

  const card = document.createElement('div');
  card.className = 'scene-card';
  card.dataset.search = (it.name + ' ' + (it.desc || '') + ' ' + groupName).toLowerCase();
  card.dataset.live = it.live || '';
  card.innerHTML = `
    <div class="scene-thumb"><iframe class="scene-thumb-frame" loading="lazy" scrolling="no" data-nw="${nativeW}" data-nh="${nativeH}" data-src="${thumbUrl()}"></iframe><span class="scene-thumb-block"></span><span class="scene-onair-pill" hidden>ON AIR</span><span class="scene-aspect">${aspect}</span></div>
    <div class="scene-card-body">
      <div class="scene-card-name">${it.name}</div>
      ${it.desc ? `<div class="scene-card-desc">${it.desc}</div>` : ''}
      <div class="scene-card-acts">
        <button class="btn btn-primary btn-xs ss-open">Open</button>
        <button class="btn btn-secondary btn-xs ss-copy">Copy</button>
        <button class="btn btn-ghost btn-xs ss-settings" title="Settings">${svgIcon('gear')} Settings</button>
      </div>
      <div class="scene-bg-panel" hidden>
        <button class="btn btn-secondary btn-xs ss-edit scene-set-edit">Edit HTML</button>
        <label class="scene-bg-toggle"><input type="checkbox" class="ss-bg-on"><span>Background fill</span></label>
        <div class="scene-bg-controls">
          <input type="color" class="ss-bg-color" value="${bg.color || '#000000'}" title="Colour">
          <input type="range" class="ss-bg-op" min="1" max="100" value="${bg.op == null ? 50 : bg.op}" title="Opacity">
          <span class="ss-bg-op-val">${bg.op == null ? 50 : bg.op}%</span>
        </div>
        <div class="scene-bg-hint">Background fill updates live in OBS. Re-copy the URL only when adding this overlay as a new browser source.</div>
      </div>`;

  const thumb   = card.querySelector('.scene-thumb-frame');
  const bgBtn   = card.querySelector('.ss-settings');
  const panel   = card.querySelector('.scene-bg-panel');
  const onChk   = card.querySelector('.ss-bg-on');
  const colorIn = card.querySelector('.ss-bg-color');
  const opIn    = card.querySelector('.ss-bg-op');
  const opVal   = card.querySelector('.ss-bg-op-val');

  onChk.checked = !!bg.on;
  const reflect = () => bgBtn.classList.toggle('on', !!bg.on);
  reflect();
  function refreshThumb() {
    const src = thumbUrl();
    if (thumb.src) {
      thumb.addEventListener('load', function onl() { thumb.removeEventListener('load', onl); if (typeof _scaleThumb === 'function') _scaleThumb(thumb); }, { once: true });
      thumb.src = src;
    } else { thumb.dataset.src = src; }
  }
  function persist() { saveSceneBg(it.path, bg); send('set_scene_bg', { path: it.path, bg }); reflect(); refreshThumb(); }

  bgBtn.addEventListener('click', (e) => { e.stopPropagation(); panel.hidden = !panel.hidden; });
  onChk.addEventListener('change', () => { bg.on = onChk.checked; persist(); });
  colorIn.addEventListener('input', () => { bg.color = colorIn.value; persist(); });
  opIn.addEventListener('input', () => { bg.op = parseInt(opIn.value, 10); opVal.textContent = bg.op + '%'; persist(); });

  card.querySelector('.ss-open').addEventListener('click', () => window.open(liveUrl(), '_blank'));
  card.querySelector('.ss-edit').addEventListener('click', () => openSceneEditor(it.path, it.name));
  card.querySelector('.scene-thumb').addEventListener('click', () => window.open(fullPrev(), '_blank'));
  const copyBtn = card.querySelector('.ss-copy');
  copyBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const url = liveUrl();
    const done = () => { copyBtn.textContent = 'Copied!'; setTimeout(() => { copyBtn.textContent = 'Copy'; }, 1200); };
    if (navigator.clipboard) navigator.clipboard.writeText(url).then(done).catch(() => prompt('Copy URL:', url));
    else prompt('Copy URL:', url);
  });
  return card;
}

async function buildSceneSourceList() {
  const wrap = el('scene-source-list');
  if (!wrap || wrap.dataset.built) return;
  wrap.dataset.built = '1';

  let discovered = [];
  try { const r = await fetch(SCENE_BASE_URL + '/api/overlays'); const j = await r.json(); discovered = (j && j.overlays) || []; } catch {}
  const groups = mergeSceneGroups(discovered);
  const totalScenes = groups.reduce((n, g) => n + g.items.length, 0);

  // ── Top bar: search + grid/list toggle ──────────────────────────────────
  const topbar = document.createElement('div');
  topbar.className = 'scene-topbar';
  topbar.innerHTML = `
    <div class="scene-search">
      <span class="scene-search-ico">${svgIcon('search')}</span>
      <input type="text" id="scene-search-input" placeholder="Search ${totalScenes} overlays…" autocomplete="off" spellcheck="false">
      <button class="scene-search-clear" id="scene-search-clear" title="Clear" hidden>×</button>
    </div>
    <div class="scene-view-toggle">
      <button class="scene-vtog${_sceneViewMode === 'grid' ? ' active' : ''}" data-mode="grid" title="Grid view">${svgIcon('grid')}</button>
      <button class="scene-vtog${_sceneViewMode === 'list' ? ' active' : ''}" data-mode="list" title="List view">${svgIcon('list')}</button>
    </div>`;
  wrap.appendChild(topbar);

  // ── Two-column layout: sidebar nav + groups area ─────────────────────────
  const layout = document.createElement('div');
  layout.className = 'scene-layout';
  wrap.appendChild(layout);

  const nav = document.createElement('nav');
  nav.className = 'scene-nav';
  nav.id = 'scene-nav';
  layout.appendChild(nav);

  const main = document.createElement('div');
  main.className = 'scene-groups-area';
  main.id = 'scene-groups-area';
  layout.appendChild(main);

  // ── Sidebar nav items ─────────────────────────────────────────────────────
  const mkNavItem = (key, label, iconHtml, count) => {
    const b = document.createElement('button');
    b.className = 'scene-nav-item' + (key === _sceneFilterGroup ? ' active' : '');
    b.dataset.group = key;
    b.innerHTML = (iconHtml ? `<span class="scene-nav-ico">${iconHtml}</span>` : '') + `<span class="scene-nav-label">${label}</span><span class="scene-nav-count">${count}</span>`;
    b.addEventListener('click', () => { _sceneFilterGroup = key; applySceneFilter(); });
    return b;
  };
  nav.appendChild(mkNavItem('all', 'All', '', totalScenes));
  const onAirItem = mkNavItem('__onair', 'On Air', '<span class="scene-chip-dot"></span>', 0);
  onAirItem.id = 'scene-nav-onair';
  nav.appendChild(onAirItem);
  const navSep = document.createElement('div');
  navSep.className = 'scene-nav-sep';
  nav.appendChild(navSep);
  groups.forEach((g) => nav.appendChild(mkNavItem(g.group, g.group, svgIcon(g.icon), g.items.length)));

  // ── Groups: grid cards + list rows ────────────────────────────────────────
  groups.forEach((g) => {
    const section = document.createElement('div');
    section.className = 'scene-group';
    section.dataset.group = g.group;
    const head = document.createElement('div');
    head.className = 'scene-group-head';
    head.innerHTML = `<span class="scene-group-ico">${svgIcon(g.icon)}</span><span class="scene-group-name">${g.group}</span><span class="scene-group-count">${g.items.length}</span>`;
    section.appendChild(head);
    const grid = document.createElement('div');
    grid.className = 'scene-card-grid';
    grid.hidden = _sceneViewMode !== 'grid';
    const listWrap = document.createElement('div');
    listWrap.className = 'scene-row-list';
    listWrap.hidden = _sceneViewMode !== 'list';
    g.items.forEach((it) => {
      grid.appendChild(buildSceneCard(it, g.group));
      listWrap.appendChild(buildSceneRow(it, g.group));
    });
    section.appendChild(grid);
    section.appendChild(listWrap);
    main.appendChild(section);
  });

  // ── Search ────────────────────────────────────────────────────────────────
  const search = topbar.querySelector('#scene-search-input');
  const clearBtn = topbar.querySelector('#scene-search-clear');
  search.addEventListener('input', () => {
    _sceneFilterText = search.value.trim().toLowerCase();
    clearBtn.hidden = !_sceneFilterText;
    applySceneFilter();
  });
  clearBtn.addEventListener('click', () => { search.value = ''; _sceneFilterText = ''; clearBtn.hidden = true; applySceneFilter(); });

  // ── View toggle ───────────────────────────────────────────────────────────
  topbar.querySelectorAll('.scene-vtog').forEach((b) => {
    b.addEventListener('click', () => {
      _sceneViewMode = b.dataset.mode;
      topbar.querySelectorAll('.scene-vtog').forEach((x) => x.classList.toggle('active', x.dataset.mode === _sceneViewMode));
      applySceneViewMode();
      applySceneFilter();
      if (_sceneViewMode === 'grid' && typeof loadScenePreviews === 'function') loadScenePreviews();
      else if (typeof unloadScenePreviews === 'function') unloadScenePreviews();
    });
  });

  refreshSceneOnAir(currentState);
  if (el('tab-media-content')?.classList.contains('active') && _assetsTab === 'overlays' && typeof loadScenePreviews === 'function') loadScenePreviews();
}

// Show/hide grid cards or list rows to match active sidebar group + search text.
function applySceneViewMode() {
  const isGrid = _sceneViewMode === 'grid';
  document.querySelectorAll('.scene-card-grid').forEach((g) => { g.hidden = !isGrid; });
  document.querySelectorAll('.scene-row-list').forEach((l) => { l.hidden = isGrid; });
}

function applySceneFilter() {
  const wrap = el('scene-source-list');
  if (!wrap) return;
  document.querySelectorAll('#scene-nav .scene-nav-item').forEach((b) =>
    b.classList.toggle('active', b.dataset.group === _sceneFilterGroup));
  const isGrid = _sceneViewMode === 'grid';
  let totalShown = 0;
  wrap.querySelectorAll('.scene-group').forEach((section) => {
    const groupName = section.dataset.group;
    let shown = 0;
    const matchItem = (item) => {
      const matchText = !_sceneFilterText || item.dataset.search.includes(_sceneFilterText);
      let matchGroup = true;
      if (_sceneFilterGroup === '__onair') matchGroup = item.classList.contains('is-onair');
      else if (_sceneFilterGroup !== 'all') matchGroup = groupName === _sceneFilterGroup;
      return matchText && matchGroup;
    };
    section.querySelectorAll(isGrid ? '.scene-card' : '.scene-row').forEach((item) => {
      const show = matchItem(item);
      item.style.display = show ? '' : 'none';
      if (show) shown++;
    });
    section.style.display = shown ? '' : 'none';
    totalShown += shown;
  });
  let empty = el('scene-empty');
  if (!empty) {
    empty = document.createElement('div');
    empty.id = 'scene-empty';
    empty.className = 'scene-empty';
    empty.textContent = 'No overlays match your search.';
    const groupsArea = el('scene-groups-area');
    if (groupsArea) groupsArea.appendChild(empty);
    else wrap.appendChild(empty);
  }
  empty.style.display = totalShown ? 'none' : '';
}

// Light up the ON AIR pill on any scene whose `live` state path is currently truthy.
function refreshSceneOnAir(state) {
  const wrap = el('scene-source-list');
  if (!wrap || !wrap.dataset.built) return;
  let liveCount = 0;
  wrap.querySelectorAll('.scene-card').forEach((card) => {
    const key = card.dataset.live;
    let on = false;
    if (key && key !== 'always') on = !!getPath(state || {}, key);
    card.classList.toggle('is-onair', on);
    const pill = card.querySelector('.scene-onair-pill');
    if (pill) pill.hidden = !on;
    if (on) liveCount++;
  });
  wrap.querySelectorAll('.scene-row').forEach((row) => {
    const key = row.dataset.live;
    let on = false;
    if (key && key !== 'always') on = !!getPath(state || {}, key);
    row.classList.toggle('is-onair', on);
    const pill = row.querySelector('.sr-air');
    if (pill) pill.hidden = !on;
  });
  const navOnAir = el('scene-nav-onair');
  if (navOnAir) { const c = navOnAir.querySelector('.scene-nav-count'); if (c) c.textContent = liveCount; }
  const badge = el('scene-onair-count');
  if (badge) { badge.textContent = liveCount ? `${liveCount} on air` : ''; badge.style.display = liveCount ? '' : 'none'; }
  if (_sceneFilterGroup === '__onair') applySceneFilter();
}

// Scene preview iframes each load a full overlay (WebSocket + animation loops),
// so we only let them run while the Scenes tab is open. Loading is staggered to
// avoid a burst locking up the main thread. After each frame loads we inject
// body.style.zoom so the 1920×1080 scene scales to fit the thumbnail box.
let _scenePreviewTimer = null;
// Scale the whole iframe (rendered at the scene's native size) down to fit its thumbnail box.
// Works regardless of how the overlay scales itself internally.
function _scaleThumb(f) {
  try {
    const box = f.parentElement; if (!box) return;
    const bw = box.clientWidth, bh = box.clientHeight;
    if (!bw || !bh) return;
    const nw = parseInt(f.dataset.nw, 10) || 1920;
    const nh = parseInt(f.dataset.nh, 10) || 1080;
    f.style.width = nw + 'px';
    f.style.height = nh + 'px';
    const s = Math.min(bw / nw, bh / nh);
    f.style.transform = `translate(${(bw - nw * s) / 2}px, ${(bh - nh * s) / 2}px) scale(${s})`;
  } catch (e) {}
}
// Keep all visible thumbs correctly scaled when the window/grid resizes.
let _thumbResizeTimer = null;
window.addEventListener('resize', () => {
  clearTimeout(_thumbResizeTimer);
  _thumbResizeTimer = setTimeout(() => { document.querySelectorAll('.scene-thumb-frame[src]').forEach(_scaleThumb); }, 150);
});
function loadScenePreviews() {
  if (_scenePreviewTimer) { clearTimeout(_scenePreviewTimer); _scenePreviewTimer = null; }
  const frames = Array.from(document.querySelectorAll('.scene-thumb-frame[data-src]'));
  let i = 0;
  const step = () => {
    if (i >= frames.length) { _scenePreviewTimer = null; return; }
    const f = frames[i++];
    if (!f.src) {
      f.addEventListener('load', function () { _scaleThumb(f); }, { once: true });
      f.src = f.dataset.src;
    }
    _scenePreviewTimer = setTimeout(step, 120);
  };
  step();
}
function unloadScenePreviews() {
  if (_scenePreviewTimer) { clearTimeout(_scenePreviewTimer); _scenePreviewTimer = null; }
  document.querySelectorAll('.scene-thumb-frame').forEach((f) => { if (f.src) f.removeAttribute('src'); });
}

// ── Scene HTML editor (code + live preview, backed by /api/overlay/*) ───────
let _seScene = null;        // { path, name }
let _seTimer = null;
function seStatus(msg, ok) { const s = el('se-status'); if (s) { s.textContent = msg || ''; s.style.color = ok === false ? '#f56565' : (ok ? 'var(--good,#48bb78)' : 'var(--muted)'); } }
// Render the edited HTML in the preview iframe. Inject a <base> so the scene's
// relative assets (scene.css, app.js, images) still resolve to the server.
function seRenderPreview() {
  const frame = el('se-preview'); const code = el('se-code');
  if (!frame || !code) return;
  let html = code.value;
  const baseTag = `<base href="${SCENE_BASE_URL}/">`;
  if (/<head[^>]*>/i.test(html)) html = html.replace(/<head([^>]*)>/i, `<head$1>${baseTag}`);
  else html = baseTag + html;
  frame.srcdoc = html;
}
async function openSceneEditor(path, name) {
  // The source file is the same regardless of any ?query params on the URL (e.g. ?src=main).
  path = String(path).split('?')[0];
  _seScene = { path, name };
  el('se-title').textContent = name || path;
  el('se-code').value = '';
  seStatus('Loading…');
  el('scene-editor-modal').style.display = 'flex';
  try {
    const r = await fetch(`${SCENE_BASE_URL}/api/overlay/source?path=${encodeURIComponent(path)}`);
    const d = await r.json();
    if (!d.ok) throw new Error(d.message || 'Load failed');
    el('se-code').value = d.content || '';
    seStatus(d.isOverride ? 'Editing your saved override.' : '');
    seRenderPreview();
  } catch (e) { seStatus(e.message || 'Could not load source.', false); }
}
function seClose() { el('scene-editor-modal').style.display = 'none'; _seScene = null; }
el('se-close')?.addEventListener('click', seClose);
el('se-refresh')?.addEventListener('click', seRenderPreview);
el('se-code')?.addEventListener('input', () => { clearTimeout(_seTimer); _seTimer = setTimeout(seRenderPreview, 500); });
el('se-save')?.addEventListener('click', async () => {
  if (!_seScene) return;
  seStatus('Saving…');
  try {
    const r = await fetch(`${SCENE_BASE_URL}/api/overlay/save`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: _seScene.path, content: el('se-code').value }) });
    const d = await r.json();
    if (!d.ok) throw new Error(d.message || 'Save failed');
    seStatus('Saved — the live browser source now uses your version.', true);
  } catch (e) { seStatus(e.message || 'Save failed.', false); }
});
el('se-revert')?.addEventListener('click', async () => {
  if (!_seScene) return;
  if (!await appConfirm('Remove your override and restore the original scene?', 'Restore Original')) return;
  seStatus('Reverting…');
  try {
    const r = await fetch(`${SCENE_BASE_URL}/api/overlay/revert`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: _seScene.path }) });
    const d = await r.json();
    if (!d.ok) throw new Error(d.message || 'Revert failed');
    // revert doesn't return the source — re-fetch the original to reload the editor.
    const sr = await fetch(`${SCENE_BASE_URL}/api/overlay/source?path=${encodeURIComponent(_seScene.path)}`);
    const sd = await sr.json();
    if (sd.ok) el('se-code').value = sd.content || '';
    seStatus('Reverted to the original.', true);
    seRenderPreview();
  } catch (e) { seStatus(e.message || 'Revert failed.', false); }
});

function renderWatchlistInfo(data) {
  const infoEl = el('ck-watchlist-info'); if (!infoEl) return;
  const teams = (data.watchlist && data.watchlist.teams) || [];
  if (!teams.length) {
    infoEl.textContent = 'No teams — star teams on Events tab';
  } else {
    infoEl.textContent = teams.map((t) => t.name || '').filter(Boolean).join(', ');
  }
}

// Reflect live visibility into the toggles + card highlight.
function renderScenePresets(data) {
  const presets = data.scenePresets || {};
  document.querySelectorAll('.gfx-cust-bar[data-scene]').forEach((bar) => {
    const key = bar.dataset.scene;
    const sp = presets[key] || { active: 'Default', presets: {} };
    const active = sp.active || 'Default';
    const names = ['Default', ...Object.keys(sp.presets || {}).filter((n) => n !== 'Default' && n !== '__preview__')];
    const sig = active + '|' + names.join(',');

    const sel  = bar.querySelector(`[data-cust-sel="${key}"]`);
    const lbl  = bar.querySelector(`[data-cust-active="${key}"]`);
    if (sel && sel.dataset.rspSig !== sig) {
      sel.innerHTML = names.map((n) => `<option value="${n}"${n === active ? ' selected' : ''}>${n}</option>`).join('');
      sel.dataset.rspSig = sig;
    }
    if (lbl) lbl.textContent = active;

    // Update color pickers and font selector from the active preset's config (skip __preview__).
    if (active === '__preview__') return;
    const cfg = ((sp.presets || {})[active] || {}).config || {};
    const c1  = bar.querySelector(`[data-cust-c1="${key}"]`);
    const c2  = bar.querySelector(`[data-cust-c2="${key}"]`);
    const fnt = bar.querySelector(`[data-cust-font="${key}"]`);
    const GFX_DA  = '#e83a8b';
    const GFX_DA2 = '#8b5cf6';
    if (c1)  c1.value  = cfg.accent  || GFX_DA;
    if (c2)  c2.value  = cfg.accent2 || GFX_DA2;
    if (fnt) fnt.value = cfg.font    || '';
  });
}

function applyScenesCockpit(data) {
  renderCockpitStatus(data);
  renderWatchlistInfo(data);
  ONAIR_SCENES.forEach((s) => {
    const on = !!getPath(data, s.path);
    const cb = el('air-' + s.key);
    if (cb && document.activeElement !== cb) cb.checked = on;
    const card = el('air-card-' + s.key);
    if (card) card.classList.toggle('live', on);
    const st = el('air-state-' + s.key);
    if (st) st.textContent = on ? 'SHOWN' : 'HIDDEN';
  });
}

document.querySelectorAll('.js-cut-all').forEach((btn) => {
  btn.addEventListener('click', () => ONAIR_SCENES.forEach((s) => send(s.msg, { visible: false })));
});

// ── "Go Live" triggers — one toggle per graphic that reflects what's ON AIR ──
// Each button shows the graphic's live state (green "On Air" when visible) and a
// single click flips it: live → hide, off → show with the row's current options.
const GOLIVE_TRIGGERS = [
  { toggle: 'ck-break-toggle',    state: 'breakScreen', sceneKey: 'break',    msg: 'set_break',    show: () => startBreakFromRail() },
  { toggle: 'ck-matchup-toggle',  state: 'matchup',     sceneKey: 'matchup',  pushOnly: true },
  { toggle: 'ck-winner-toggle',   state: 'winner',      sceneKey: 'winner',   msg: 'set_winner',   show: () => ({ visible: true, side: el('ck-winner-side')?.value || 'blue' }) },
  { toggle: 'ck-intro-toggle',    state: 'intro',       sceneKey: 'intro',    msg: 'set_intro',    show: () => ({ visible: true, side: el('ck-intro-side')?.value || 'blue' }) },
  { toggle: 'ck-veto-toggle',     state: 'veto',        sceneKey: 'veto',     msg: 'set_veto',     show: () => ({ visible: true }) },
  { toggle: 'ck-spotlight-toggle',state: 'watchlist',   sceneKey: 'spotlight',msg: 'set_watchlist',show: () => ({ visible: true }) },
  { toggle: 'ck-schedule-toggle', state: 'upcoming',    sceneKey: 'schedule', msg: 'set_upcoming', show: () => ({ visible: true }) },
];
GOLIVE_TRIGGERS.forEach((t) => {
  el(t.toggle)?.addEventListener('click', () => {
    const gfxLive = !!(currentState && currentState.gfxActive === t.sceneKey);
    const overlayLive = !!(currentState && currentState[t.state] && currentState[t.state].visible);
    const live = gfxLive || overlayLive;
    if (live) {
      if (!t.pushOnly) send(t.msg, { visible: false });
      send('set_gfx_active', { scene: '' });
      if (currentState) currentState.gfxActive = '';
      if (typeof refreshTopBar === 'function') refreshTopBar('');
    } else {
      // Clear whichever GFX scene is currently active before pushing ours.
      const prev = currentState && currentState.gfxActive;
      if (prev && prev !== t.sceneKey && typeof SCENE_META !== 'undefined' && SCENE_META[prev]) {
        const pm = SCENE_META[prev];
        el(pm.clearId || ('btn-hide-' + prev))?.click();
      }
      if (!t.pushOnly) send(t.msg, t.show());
      send('set_gfx_active', { scene: t.sceneKey });
      if (currentState) currentState.gfxActive = t.sceneKey;
      if (typeof refreshTopBar === 'function') refreshTopBar(t.sceneKey);
      if (el('gfx-autocut-on')?.checked) {
        const sc = (el('gfx-autocut-scene')?.value || '').trim();
        if (sc) send('obs_switch_scene', { sceneName: sc });
      }
    }
  });
});
// All trigger graphics share one browser source (overlay/triggers.html).
el('btn-copy-triggers-url')?.addEventListener('click', (e) => {
  const url = (typeof SCENE_BASE_URL !== 'undefined' ? SCENE_BASE_URL : 'http://localhost:3000') + '/triggers.html';
  if (typeof copyText === 'function') copyText(url, e.currentTarget);
  else if (navigator.clipboard) navigator.clipboard.writeText(url);
});
// Copy the standalone countdown overlay URL from the rail Countdown trigger.
el('ck-break-copy')?.addEventListener('click', (e) => {
  const url = (typeof SCENE_BASE_URL !== 'undefined' ? SCENE_BASE_URL : 'http://localhost:3000') + '/countdown.html';
  if (typeof copyText === 'function') copyText(url, e.currentTarget);
  else if (navigator.clipboard) navigator.clipboard.writeText(url);
});
// Pop the whole Go Live trigger bar out into its own window.
el('gl-popout')?.addEventListener('click', () => openPopout('triggers'));

function renderGoLive(data) {
  let liveCount = 0;
  GOLIVE_TRIGGERS.forEach((t) => {
    const btn = el(t.toggle); if (!btn) return;
    const live = !!(data[t.state] && data[t.state].visible) || data.gfxActive === t.sceneKey;
    if (live) liveCount++;
    const row = btn.closest('.gl-row');
    if (row) row.classList.toggle('live', live);
    btn.textContent = live ? '● On Air' : 'Push Live';
    btn.title = live ? 'Click to take off air' : 'Push this graphic live';
  });
  const count = el('gl-live-count');
  if (count) count.textContent = liveCount ? `${liveCount} live` : '';
  const dot = el('qrail-golive-dot');
  if (dot) dot.classList.toggle('on', liveCount > 0);   // live indicator on the Go Live rail tab
  const view = data.view || 'hud';
  document.querySelectorAll('#gl-view-seg .gl-seg-btn').forEach((b) => {
    b.classList.toggle('active', b.dataset.view === view);
  });
}
el('ck-view-scoreboard')?.addEventListener('click', () => send('force_scoreboard'));
el('ck-view-hud')?.addEventListener('click', () => send('force_hud'));

// ══════════════ Events tab — start.gg admin tournaments + sponsorship data ══════════════
const EV_API = 'http://localhost:3000/api/startgg';
let _evDetail = null;
let _evTournaments = [];
let _evFilter = 'upcoming';   // 'upcoming' | 'past' | 'all'
let _evSearch = '';
let _evMode = 'mine';         // 'mine' = my admin tournaments | 'search' = global start.gg search
let _evSource = 'startgg';    // 'startgg' | 'challonge' | 'nxgen' — which platform the grid is showing

function evStatus(msg, kind) {
  const s = el('ev-status'); if (!s) return;
  s.textContent = msg || '';
  s.className = 'ev-status' + (kind ? ' ev-' + kind : '');
}
function fmtEvDate(ts) {
  if (!ts) return '';
  try { return new Date(ts * 1000).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); } catch { return ''; }
}
async function evPost(path, body) {
  const r = await fetch(EV_API + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}) });
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data.error || ('HTTP ' + r.status));
  return data;
}
// Auto-load the producer's in-house tournaments when the Competitions tab first opens — instant
// from the local cache, then refreshed from start.gg in the background. No button click needed.
let _evAutoLoaded = false;
function evAutoLoad() {
  if (_evAutoLoaded) return;
  _evAutoLoaded = true;
  _evMode = 'mine';
  let cachedCount = 0;
  try {
    const c = JSON.parse(localStorage.getItem('ne_my_tournaments') || 'null');
    if (c && Array.isArray(c.tournaments) && c.tournaments.length) {
      _evTournaments = c.tournaments; cachedCount = c.tournaments.length;
      if (typeof evSetMode === 'function') evSetMode('My tournaments');
      const toolbar = el('ev-toolbar'); if (toolbar) toolbar.style.display = '';
      applyEventsView();
    }
  } catch (e) {}
  evLoadTournaments({ silent: cachedCount > 0 });   // refresh from start.gg (quiet if we showed cache)
}
async function evLoadTournaments(opts) {
  opts = opts || {};
  _evMode = 'mine';
  const btn = el('ev-load'); if (btn) btn.disabled = true;
  if (!opts.silent) evStatus('Loading your tournaments…');
  try {
    const data = await evPost('/my-tournaments', {});
    _evTournaments = data.tournaments || [];
    try { localStorage.setItem('ne_my_tournaments', JSON.stringify({ tournaments: _evTournaments, at: Date.now() })); } catch (e) {}
    _evSearch = (el('ev-search')?.value || '').trim();   // box filters the loaded list in mine mode
    const toolbar = el('ev-toolbar'); if (toolbar) toolbar.style.display = '';
    if (typeof evSetMode === 'function') evSetMode('My tournaments');
    applyEventsView();
    evStatus(_evTournaments.length ? '' : 'No tournaments found for this token — confirm you admin/staff events and your token is set in Settings → start.gg.');
  } catch (e) {
    if (!opts.silent) evStatus(e.message || 'Failed to load. Check your start.gg token in Settings.', 'err');
  } finally { if (btn) btn.disabled = false; }
}
// Challonge and NXGEN tournaments are one bracket each (no nested "events" the way a start.gg
// tournament can have), so they're normalized into the same card shape as start.gg tournaments —
// same search/filter/sort in applyEventsView() — but tagged with `platform` so renderEventsGrid()
// gives them inline "+ My Events" / "Set live" actions instead of a detail-drilldown click.
async function evLoadChallongeTournaments() {
  const btn = el('ev-load'); if (btn) btn.disabled = true;
  evStatus('Loading your Challonge tournaments…');
  try {
    const r = await fetch('http://localhost:3000/api/challonge/my-tournaments', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || ('HTTP ' + r.status));
    _evTournaments = (data.tournaments || []).map((t) => ({
      platform: 'challonge', slug: t.slug, name: t.name,
      startAt: t.startedAt ? Math.floor(new Date(t.startedAt).getTime() / 1000) : null,
      numAttendees: t.participantsCount || 0, eventCount: 1, image: t.logo || '', game: t.gameName || '',
    }));
    evSetMode('Challonge — my tournaments');
    applyEventsView();
    evStatus(_evTournaments.length ? '' : 'No Challonge tournaments found — confirm your API key in Settings → Integrations.');
  } catch (e) {
    evStatus(e.message || 'Failed to load. Check your Challonge API key in Settings.', 'err');
  } finally { if (btn) btn.disabled = false; }
}
async function evLoadNxgenTournaments() {
  const btn = el('ev-load'); if (btn) btn.disabled = true;
  evStatus('Loading your NXGEN events…');
  try {
    const r = await fetch('http://localhost:3000/api/nxgen/events', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ limit: 100, includePast: true }) });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || ('HTTP ' + r.status));
    _evTournaments = (data.events || []).map((e) => ({
      platform: 'nxgen', slug: e.slug, name: e.name,
      startAt: e.eventDate ? Math.floor(new Date(e.eventDate).getTime() / 1000) || null : null,
      numAttendees: e.participantCount || 0, eventCount: 1, image: e.coverImage || '', game: e.activity || '',
    }));
    evSetMode('NXGEN — events');
    applyEventsView();
    evStatus(_evTournaments.length ? '' : 'No NXGEN events found — confirm your API key in Settings → Integrations.');
  } catch (e) {
    evStatus(e.message || 'Failed to load. Check your NXGEN API key in Settings.', 'err');
  } finally { if (btn) btn.disabled = false; }
}
// Switch which platform the Tournaments grid is showing.
function evSetSource(src) {
  _evSource = ['challonge', 'nxgen'].includes(src) ? src : 'startgg';
  document.querySelectorAll('#ev-src-seg .ev-seg-btn').forEach((b) => b.classList.toggle('active', b.dataset.src === _evSource));
  const searchbar = el('ev-searchbar'); if (searchbar) searchbar.style.display = _evSource === 'startgg' ? '' : 'none';
  const loadBtn = el('ev-load');
  if (loadBtn) loadBtn.textContent = _evSource === 'challonge' ? 'My Challonge tournaments' : _evSource === 'nxgen' ? 'My NXGEN events' : 'My tournaments';
  _evTournaments = []; _evDetail = null;
  const sec = el('ev-detail-section'); if (sec) sec.style.display = 'none';
  const toolbar = el('ev-toolbar'); if (toolbar) toolbar.style.display = '';
  if (_evSource === 'challonge') evLoadChallongeTournaments();
  else if (_evSource === 'nxgen') evLoadNxgenTournaments();
  else evLoadTournaments();
}
document.querySelectorAll('#ev-src-seg .ev-seg-btn').forEach((b) => b.addEventListener('click', () => evSetSource(b.dataset.src)));
// Filter (upcoming/past/all) + name search + sort, then render. Default: upcoming,
// soonest tournament first → farthest. Past: most recent first.
function evStartTs(t) { return t.startAt || t.endAt || 0; }
function evIsUpcoming(t, now) { return (t.endAt || t.startAt || 0) >= now; }
function applyEventsView() {
  const now = Date.now() / 1000;
  const q = _evSearch.trim().toLowerCase();
  let list = _evTournaments.slice();
  if (q) list = list.filter((t) => (t.name || '').toLowerCase().includes(q) || (t.slug || '').toLowerCase().includes(q));

  const upAsc = (a, b) => (evStartTs(a) || Infinity) - (evStartTs(b) || Infinity);   // soonest first
  const pastDesc = (a, b) => evStartTs(b) - evStartTs(a);                             // most recent first
  if (_evFilter === 'upcoming') list = list.filter((t) => evIsUpcoming(t, now)).sort(upAsc);
  else if (_evFilter === 'past') list = list.filter((t) => !evIsUpcoming(t, now)).sort(pastDesc);
  else list = list.filter((t) => evIsUpcoming(t, now)).sort(upAsc)
    .concat(list.filter((t) => !evIsUpcoming(t, now)).sort(pastDesc));

  const cnt = el('ev-count');
  if (cnt) cnt.textContent = list.length + (list.length === 1 ? ' tournament' : ' tournaments');
  renderEventsGrid(list, now);
}
function evRelDate(ts, now) {
  if (!ts) return '';
  const days = Math.round((ts - now) / 86400);
  if (days === 0) return 'today';
  if (days > 0) return days === 1 ? 'tomorrow' : (days < 14 ? `in ${days} days` : (days < 60 ? `in ${Math.round(days / 7)} weeks` : `in ${Math.round(days / 30)} months`));
  const ago = -days;
  return ago === 1 ? 'yesterday' : (ago < 14 ? `${ago} days ago` : (ago < 60 ? `${Math.round(ago / 7)} weeks ago` : `${Math.round(ago / 30)} months ago`));
}
function renderEventsGrid(list, now) {
  const grid = el('ev-grid'); if (!grid) return;
  now = now || Date.now() / 1000;
  const sec = el('ev-detail-section'); if (sec) sec.style.display = 'none';
  grid.style.display = '';
  grid.innerHTML = '';
  if (!list.length) {
    grid.innerHTML = `<div class="ev-empty" style="grid-column:1/-1;">${_evSearch ? 'No tournaments match your search.' : 'No ' + (_evFilter === 'all' ? '' : _evFilter + ' ') + 'tournaments.'}</div>`;
    return;
  }
  list.forEach((t) => {
    const past = !evIsUpcoming(t, now);
    const platform = t.platform || 'startgg';
    // Start.gg tournaments can hold several events, so the whole card is a <button> that drills
    // into the detail view (unchanged). Challonge/NXGEN tournaments are one bracket each — a plain
    // <div> card with its own inline action <button>s (a <button> can't nest another <button>).
    const card = document.createElement(platform === 'startgg' ? 'button' : 'div');
    card.className = 'ev-card' + (past ? ' ev-card-past' : '');
    const platformBadge = platform !== 'startgg' ? `<span class="ev-pill ev-pill-src">${platform === 'challonge' ? 'CHALLONGE' : 'NXGEN'}</span>` : '';
    card.innerHTML = `<div class="ev-card-img"></div><div class="ev-card-body">
      <div class="ev-card-name"></div><div class="ev-card-meta"></div>
      <div class="ev-card-stats">${platformBadge}<span class="ev-pill"></span><span class="ev-pill"></span></div>
      ${platform !== 'startgg' ? '<div class="ev-card-acts"><button type="button" class="btn btn-secondary btn-sm ev-card-addmy">+ My Events</button><button type="button" class="btn btn-primary btn-sm ev-card-live">Set live</button></div>' : ''}</div>`;
    const img = card.querySelector('.ev-card-img');
    if (t.image) { const i = document.createElement('img'); i.src = t.image; i.alt = ''; img.appendChild(i); }
    else img.textContent = (t.name || '?').slice(0, 1).toUpperCase();
    card.querySelector('.ev-card-name').textContent = t.name || '(untitled)';
    const rel = evRelDate(evStartTs(t), now);
    card.querySelector('.ev-card-meta').textContent = [fmtEvDate(t.startAt), rel, [t.city, t.countryCode].filter(Boolean).join(', ')].filter(Boolean).join(' · ');
    const pills = card.querySelectorAll('.ev-pill:not(.ev-pill-src)');
    pills[0].textContent = (t.numAttendees || 0) + (platform === 'startgg' ? ' entrants' : ' teams');
    if (platform === 'startgg') pills[1].textContent = (t.eventCount || 0) + ' events'; else pills[1].remove();
    if (platform === 'startgg') {
      card.addEventListener('click', () => evOpenDetail(t.slug));
    } else {
      card.querySelector('.ev-card-addmy')?.addEventListener('click', (e) => {
        e.stopPropagation();
        send('add_my_event', { platform, platformSlug: t.slug, name: t.name, tournamentName: t.name, game: t.game || '', numEntrants: t.numAttendees || 0, startAt: t.startAt || null, image: t.image || '' });
        const btn = e.currentTarget; btn.textContent = 'Added ✓'; setTimeout(() => { btn.textContent = '+ My Events'; }, 1400);
      });
      card.querySelector('.ev-card-live')?.addEventListener('click', (e) => {
        e.stopPropagation();
        send(platform === 'challonge' ? 'load_challonge_tournament' : 'load_nxgen_event', { slug: t.slug });
        evStatus(`Loading "${t.name}" live…`);
      });
    }
    grid.appendChild(card);
  });
}
async function evOpenDetail(slug) {
  // Show the locally-cached detail instantly (great for past events), then refresh from the API.
  let cached = null;
  try { cached = JSON.parse(localStorage.getItem('ne_tourn_detail_' + slug) || 'null'); } catch (e) {}
  if (cached && cached.detail) { _evDetail = cached.detail; renderEventDetail(cached.detail); evStatus('Refreshing…'); }
  else evStatus('Loading tournament…');
  try {
    const data = await evPost('/tournament-detail', { slug });
    _evDetail = data.detail;
    renderEventDetail(data.detail);
    try { localStorage.setItem('ne_tourn_detail_' + slug, JSON.stringify({ detail: data.detail, at: Date.now() })); } catch (e) {}
    evStatus('');
  } catch (e) { if (!cached) evStatus(e.message || 'Failed to load tournament.', 'err'); else evStatus(''); }
}
let _evTeams = [];            // teams (with players) of the currently-selected event
let _evTeamsCache = {};       // eventSlug → teams (avoid refetching)
let _evSelSlug = '';          // selected event slug
let _evSelName = '';          // selected event name (→ Teams to Watch subtitle)
const _evEsc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
function renderEventDetail(d) {
  _evDetail = d;
  const grid = el('ev-grid'); if (grid) grid.style.display = 'none';
  const sec = el('ev-detail-section'); if (sec) sec.style.display = '';
  el('ev-detail-name').textContent = d.name || '';
  const s = d.summary || {};
  // Hero
  const logo = el('ev-hero-logo'); if (logo) { logo.innerHTML = ''; if (d.image) { const i = document.createElement('img'); i.src = d.image; i.alt = ''; logo.appendChild(i); } else logo.textContent = (d.name || '?').slice(0, 1).toUpperCase(); }
  const bg = el('ev-hero-bg'); if (bg) bg.style.backgroundImage = d.image ? `url("${d.image}")` : 'none';
  const dateRange = [fmtEvDate(s.startAt), fmtEvDate(s.endAt)].filter(Boolean).join(' – ');
  const meta = el('ev-hero-meta'); if (meta) meta.textContent = [dateRange, d.location, (s.attendees || 0) + ' attendees'].filter(Boolean).join('  ·  ');
  const games = el('ev-hero-games'); if (games) games.innerHTML = (d.games || []).map((g) => `<span class="ev-game-chip">${_evEsc(g)}</span>`).join('');
  const sgg = el('ev-hero-startgg'); if (sgg) sgg.href = 'https://www.start.gg/' + (d.slug || '');
  // Stat cards
  const stats = [
    ['Attendees', s.attendees || 0], ['Events', s.eventCount || 0],
    ['Total entrants', s.totalEntrants || 0], ['Unique players', s.uniquePlayers || 0],
    ['Games', s.gameCount || 0], ['Dates', dateRange || '—'],
  ];
  const sg = el('ev-stat-grid'); sg.innerHTML = '';
  stats.forEach(([k, v]) => {
    const cell = document.createElement('div'); cell.className = 'ev-stat';
    cell.innerHTML = '<div class="ev-stat-v"></div><div class="ev-stat-k"></div>';
    cell.querySelector('.ev-stat-v').textContent = v;
    cell.querySelector('.ev-stat-k').textContent = k;
    sg.appendChild(cell);
  });
  // Events — clickable cards (select → load teams) with quick actions
  el('ev-events-count').textContent = (d.events || []).length;
  const ev = el('ev-events-list'); ev.innerHTML = '';
  (d.events || []).forEach((e) => {
    const row = document.createElement('div'); row.className = 'ev-event-row'; row.dataset.slug = e.slug;
    row.innerHTML = '<div class="ev-event-info"><div class="ev-event-name"></div><div class="ev-event-sub"></div></div>'
      + '<div class="ev-event-acts"><button class="btn btn-secondary btn-sm ev-add-my" title="Save this event to My Events (live sync + seeding)">+ My Events</button>'
      + '<button class="btn btn-primary btn-sm ev-activate" title="Import all teams + load the bracket and make this the live broadcast event">Set live</button></div>';
    row.querySelector('.ev-event-name').textContent = e.name;
    row.querySelector('.ev-event-sub').textContent = [e.game, (e.numEntrants || 0) + ' teams', e.state].filter(Boolean).join(' · ');
    row.querySelector('.ev-activate').addEventListener('click', (cev) => { cev.stopPropagation(); evActivateEvent(d, e); });
    row.querySelector('.ev-add-my').addEventListener('click', (clickEv) => {
      clickEv.stopPropagation();
      send('add_my_event', { eventSlug: e.slug, tournamentSlug: d.slug || '', name: e.name, tournamentName: d.name || '', game: e.game || '', numEntrants: e.numEntrants || 0, startAt: e.startAt || null, image: d.image || '' });
      const btn = clickEv.currentTarget; btn.textContent = 'Added ✓'; setTimeout(() => { btn.textContent = '+ My Events'; }, 1400);
    });
    row.addEventListener('click', () => evSelectEvent(e));
    ev.appendChild(row);
  });
  // Auto-select the first (or biggest) event so its teams show immediately.
  const first = (d.events || []).slice().sort((a, b) => (b.numEntrants || 0) - (a.numEntrants || 0))[0];
  if (first) evSelectEvent(first); else { _evTeams = []; renderEventTeams(''); }
  el('ev-sponsor-text').textContent = buildSponsorSummary(d);
}
// Select an event → highlight it + load its teams (with players) into the right column.
async function evSelectEvent(e) {
  _evSelSlug = e.slug; _evSelName = e.name || '';
  document.querySelectorAll('#ev-events-list .ev-event-row').forEach((r) => r.classList.toggle('is-sel', r.dataset.slug === e.slug));
  const title = el('ev-teams-title'); if (title) title.textContent = 'Teams · ' + (e.name || '');
  if (_evTeamsCache[e.slug]) { _evTeams = _evTeamsCache[e.slug]; renderEventTeams(el('ev-players-filter')?.value || ''); return; }
  _evTeams = []; renderEventTeams('', true);   // loading
  try {
    const r = await fetch(EV_API + '/event-seeding', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ eventSlug: e.slug }) });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || ('HTTP ' + r.status));
    _evTeams = (data.entrants || []).map((t) => ({ entrantId: t.entrantId, name: t.name, seedNum: t.seedNum, players: (t.players || []).map((p) => p.gamerTag).filter(Boolean) }));
    _evTeamsCache[e.slug] = _evTeams;
    if (_evSelSlug === e.slug) renderEventTeams(el('ev-players-filter')?.value || '');
  } catch (err) {
    if (_evSelSlug === e.slug) { const list = el('ev-players-list'); if (list) list.innerHTML = `<div class="ev-empty">Couldn't load teams: ${_evEsc(err.message)}</div>`; }
  }
}
// Render the selected event's teams as readable cards, each with its players. Searchable.
function renderEventTeams(filter, loading) {
  const list = el('ev-players-list'); if (!list) return;
  if (loading) { list.innerHTML = '<div class="ev-empty">Loading teams…</div>'; el('ev-players-count').textContent = ''; return; }
  const f = (filter || '').trim().toLowerCase();
  const shown = !f ? _evTeams : _evTeams.filter((t) => (t.name || '').toLowerCase().includes(f) || (t.players || []).some((p) => p.toLowerCase().includes(f)));
  el('ev-players-count').textContent = _evTeams.length ? _evTeams.length + ' teams · ' + _evTeams.reduce((n, t) => n + (t.players || []).length, 0) + ' players' : '';
  list.innerHTML = '';
  if (!shown.length) { list.innerHTML = `<div class="ev-empty">${_evTeams.length ? 'No teams match.' : 'No teams listed for this event yet.'}</div>`; return; }
  shown.forEach((t) => {
    const card = document.createElement('div'); card.className = 'ev-team-card';
    const players = (t.players || []).length
      ? `<div class="ev-team-players">${(t.players || []).map((p) => `<span class="ev-team-player">${_evEsc(p)}</span>`).join('')}</div>`
      : '<div class="ev-team-players ev-team-noplayers">—</div>';
    const marked = (currentState.watchlist && currentState.watchlist.teams || []).some((x) => (x.name || '').toLowerCase() === (t.name || '').toLowerCase());
    card.innerHTML = `<div class="ev-team-head">${t.seedNum ? `<span class="ev-team-seed" title="Current start.gg seed">${t.seedNum}</span>` : ''}<span class="ev-team-name">${_evEsc(t.name) || '(unnamed)'}</span><span class="ev-team-count">${(t.players || []).length}</span>`
      + `<button class="ev-team-star${marked ? ' is-on' : ''}" title="Feature in Teams to Watch">★</button></div>${players}`;
    card.querySelector('.ev-team-star').addEventListener('click', function () {
      const on = this.classList.toggle('is-on');   // optimistic
      send('toggle_watchlist_team', { team: { name: t.name, players: t.players || [], entrantId: t.entrantId || '', eventSlug: _evSelSlug }, event: _evSelName });
      evStatus(on ? `Added "${t.name}" to Teams to Watch.` : `Removed "${t.name}" from Teams to Watch.`, 'ok');
    });
    list.appendChild(card);
  });
}
function buildSponsorSummary(d) {
  const s = d.summary || {};
  return [
    d.name,
    d.location ? 'Location: ' + d.location : null,
    'Dates: ' + ([fmtEvDate(s.startAt), fmtEvDate(s.endAt)].filter(Boolean).join(' – ') || '—'),
    'Attendees: ' + (s.attendees || 0),
    'Events: ' + (s.eventCount || 0) + ' (' + (s.totalEntrants || 0) + ' total entrants)',
    'Unique players listed: ' + (s.uniquePlayers || 0),
    'Games: ' + ((s.games || []).join(', ') || '—'),
    'start.gg: https://www.start.gg/' + (d.slug || ''),
  ].filter((x) => x != null).join('\n');
}
function evActivateEvent(d, e) {
  send('activate_startgg_event', { tournamentSlug: d.slug, eventSlug: e.slug, name: e.name, tournamentName: d.name });
  evStatus(`Activating "${e.name}" — importing teams + bracket and making it the live event…`, 'ok');
}
// ── Import Teams modal (↓ Import button on Teams topbar) ──────────────────
(function () {
  const modal = el('teams-import-modal');
  function openImportModal(tab) {
    if (!modal) return;
    modal.classList.add('show');
    if (tab) switchImportTab(tab);
  }
  function closeImportModal() { modal?.classList.remove('show'); }

  function switchImportTab(tab) {
    modal?.querySelectorAll('.import-tab-btn').forEach((b) => {
      const active = b.dataset.importtab === tab;
      b.classList.toggle('active', active);
      b.style.borderBottomColor = active ? 'var(--cp-accent)' : 'transparent';
      b.style.color = active ? 'var(--text)' : 'var(--muted)';
    });
    const csvPane = el('import-tab-csv'), sggPane = el('import-tab-startgg'), jsonPane = el('import-tab-json');
    if (csvPane) csvPane.style.display = tab === 'csv' ? '' : 'none';
    if (jsonPane) jsonPane.style.display = tab === 'json' ? '' : 'none';
    if (sggPane) sggPane.style.display = tab === 'startgg' ? '' : 'none';
  }

  el('btn-teams-import')?.addEventListener('click', () => openImportModal('csv'));
  el('teams-import-modal-close')?.addEventListener('click', closeImportModal);
  modal?.addEventListener('mousedown', (e) => { if (e.target === modal) closeImportModal(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && modal?.classList.contains('show')) closeImportModal(); });

  modal?.querySelectorAll('.import-tab-btn').forEach((b) => {
    b.addEventListener('click', () => switchImportTab(b.dataset.importtab));
  });

  // CSV file status feedback
  el('teams-csv')?.addEventListener('change', () => {
    const st = el('teams-csv-status');
    if (st) { st.textContent = ''; }
  });
})();

// ── Export Teams as JSON (full backup — includes logos + player info) ───────
// CSV can't carry images, so the export is JSON: team name/colour/logo(base64) +
// each player's name/role/country/start.gg/6mans. Re-import via the Backup (JSON) tab.
el('btn-teams-export')?.addEventListener('click', () => {
  const teams = (currentState && currentState.savedTeams) || [];
  if (!teams.length) { showToast('No saved teams to export.', '#f59e0b'); return; }
  const out = teams.map((t) => ({
    name: t.name || '', color: t.color || '', logo: t.logo || null, favorite: !!t.favorite,
    players: (t.players || []).map((p) => ({ name: p.name || '', role: p.role || '', country: p.country || '', startgg: p.startgg || '', sixmans: p.sixmans || '' }))
  }));
  const payload = { app: 'NE Broadcast Suite', kind: 'teams-library', version: 1, exportedAt: new Date().toISOString(), teams: out };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = 'teams-library.json'; a.click();
  URL.revokeObjectURL(url);
  const withLogos = teams.filter((t) => t.logo).length;
  showToast(`Exported ${teams.length} team${teams.length !== 1 ? 's' : ''}${withLogos ? ` (${withLogos} with logos)` : ''}`, '#22c55e');
});

// Teams page — pull rosters straight from a start.gg event into the library.
function teamsStartggImport(slug) {
  const st = el('teams-startgg-status');
  if (!slug) { if (st) { st.textContent = 'Paste a start.gg event or tournament URL first.'; st.style.color = '#f56565'; } return; }
  send('import_startgg_teams', { eventSlug: slug });
  if (st) { st.textContent = 'Importing teams from start.gg…'; st.style.color = 'var(--muted)'; }
}
el('btn-teams-startgg-pull')?.addEventListener('click', () => {
  teamsStartggImport((el('teams-startgg-slug')?.value || '').trim());
});
el('btn-teams-use-current-event')?.addEventListener('click', () => {
  const sgg = (currentState && currentState.startgg) || {};
  const url = sgg.eventSlug
    ? 'https://www.start.gg/' + sgg.eventSlug
    : sgg.tournamentSlug
      ? 'https://www.start.gg/tournament/' + sgg.tournamentSlug
      : '';
  const inp = el('teams-startgg-slug');
  if (!url) { const st = el('teams-startgg-status'); if (st) { st.textContent = 'No start.gg event connected yet — configure one in Settings.'; st.style.color = '#f56565'; } return; }
  if (inp) inp.value = url;
  teamsStartggImport(url);
});

// ── Events sub-nav (start.gg | Leagues) ───────────────────────────────────
function evShowSubtab(t) {
  document.querySelectorAll('#ev-subnav .ev-subnav-btn').forEach((x) => x.classList.toggle('active', x.dataset.evtab === t));
  const sg = el('ev-startgg-panel'), lg = el('ev-leagues-panel'), me = el('ev-myevents-panel'), sd = el('ev-seeding-panel');
  if (sg) sg.style.display = t === 'startgg' ? '' : 'none';
  if (lg) lg.style.display = t === 'leagues' ? '' : 'none';
  if (me) me.style.display = t === 'myevents' ? '' : 'none';
  if (sd) sd.style.display = t === 'seeding' ? '' : 'none';
  if (t === 'leagues') lgRender();
  if (t === 'myevents') { renderMyEvents(); evRefreshAllOnOpen(); }
  // Land on the event picker; openSeedingStudio() re-shows the studio right after when seeding a specific event.
  if (t === 'seeding') { seedShowStudio(false); renderSeedPicker(); evRefreshAllOnOpen(); }
  try { localStorage.setItem('ev_active_subtab', t); } catch (_) {}
}
document.querySelectorAll('#ev-subnav .ev-subnav-btn').forEach((b) => b.addEventListener('click', function () { evShowSubtab(this.dataset.evtab); }));
// Reopen whichever Events sub-tab the producer was last on — survives refresh. Guarded against a
// saved tab whose button no longer exists (e.g. 'brackets'/'spotlight' get pruned from this nav).
// Deferred to a macrotask: evShowSubtab() reaches into lgRender()/renderMyEvents()/
// evRefreshAllOnOpen()/seedShowStudio()/renderSeedPicker() — calling those synchronously here
// risks the same TDZ crash documented for switchRole('monitor')/loadScenePreviews if any transitively
// touch a `let`/`const` declared further down. setTimeout(...,0) waits for the script to finish.
setTimeout(() => {
  let saved; try { saved = localStorage.getItem('ev_active_subtab'); } catch (_) {}
  if (saved && document.querySelector(`#ev-subnav .ev-subnav-btn[data-evtab="${saved}"]`)) evShowSubtab(saved);
}, 0);

// Relative "x ago" for sync timestamps.
function evAgo(ts) {
  if (!ts) return 'never';
  const s = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if (s < 60) return s < 10 ? 'just now' : s + 's ago';
  const m = Math.round(s / 60); if (m < 60) return m + 'm ago';
  const h = Math.round(m / 60); if (h < 24) return h + 'h ago';
  return Math.round(h / 24) + 'd ago';
}
function evSyncBadge(ev) {
  if (ev.syncError) return `<span class="me-sync me-sync-err" title="${(ev.syncError || '').replace(/"/g, '')}">sync failed</span>`;
  if (ev.lastSync) return `<span class="me-sync" title="Auto-syncs from start.gg every ~3 min">● synced ${evAgo(ev.lastSync)}</span>`;
  return `<span class="me-sync me-sync-wait">● awaiting sync…</span>`;
}
// Event logo (start.gg image) shown left of My Events / seeding cards; letter fallback otherwise.
function evCardLogo(ev) {
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  return ev.image
    ? `<div class="me-logo"><img src="${esc(ev.image)}" alt="" loading="lazy"></div>`
    : `<div class="me-logo me-logo-empty">${esc((ev.name || '?').slice(0, 1).toUpperCase())}</div>`;
}
// Throttle client-triggered "refresh all" so toggling tabs doesn't hammer start.gg.
let _evRefreshAt = 0;
function evRefreshAllOnOpen() {
  if (!(currentState.myEvents || []).length) return;
  if (Date.now() - _evRefreshAt < 60000) return;   // at most once / min from the client
  _evRefreshAt = Date.now();
  send('refresh_my_event', {});   // server force-refreshes every My Event
}
// ── MY EVENTS — saved start.gg events with quick actions + live sync ──────
function renderMyEvents() {
  const list = el('my-events-list'); if (!list) return;
  const empty = el('my-events-empty');
  const events = currentState.myEvents || [];
  if (empty) empty.style.display = events.length ? 'none' : '';
  list.innerHTML = '';
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
  events.forEach((ev) => {
    const platform = ev.platform || 'startgg';   // older saved entries have no field — they're start.gg
    const card = document.createElement('div'); card.className = 'my-event-card';
    const rosterN = Array.isArray(ev.roster) ? ev.roster.length : (ev.numEntrants || 0);
    const sub = [ev.game, rosterN ? rosterN + ' teams' : '', ev.tournamentName].filter(Boolean).join(' · ');
    const isLive = platform === 'challonge' ? (currentState.challonge && currentState.challonge.tournamentSlug) === ev.platformSlug
      : platform === 'nxgen' ? (currentState.nxgen && currentState.nxgen.eventSlug) === ev.platformSlug
      : platform === 'manual' ? false
      : (currentState.startgg && currentState.startgg.eventSlug) === ev.eventSlug;
    const srcBadge = platform !== 'startgg' ? ` <span class="me-src-badge">${platform === 'challonge' ? 'Challonge' : platform === 'nxgen' ? 'NXGEN' : 'Manual'}</span>` : '';
    const metaText = platform === 'startgg' ? evSyncBadge(ev) : platform === 'manual' ? 'Manual entry — no platform to sync from.' : 'No auto-sync for this platform yet — refresh manually as needed.';
    card.innerHTML = evCardLogo(ev) + `<div class="me-info"><div class="me-name">${esc(ev.name || 'Event')}${srcBadge}${isLive ? ' <span class="me-live">LIVE</span>' : ''}</div>`
      + `<div class="me-sub">${esc(sub)}</div><div class="me-meta">${metaText}</div></div>`;
    const acts = document.createElement('div'); acts.className = 'me-acts';
    const mk = (cls, label, fn, title) => { const b = document.createElement('button'); b.className = cls; b.innerHTML = label; if (title) b.title = title; b.addEventListener('click', fn); return b; };
    // "Set live" activates a platform's bracket/queue — nothing to activate for a manual entry.
    if (platform !== 'manual') {
      acts.appendChild(mk('btn btn-primary btn-sm', isLive ? 'Reload' : 'Set live', () => {
        if (platform === 'challonge') send('load_challonge_tournament', { slug: ev.platformSlug });
        else if (platform === 'nxgen') send('load_nxgen_event', { slug: ev.platformSlug });
        else send('activate_startgg_event', { eventSlug: ev.eventSlug, tournamentSlug: ev.tournamentSlug });
      }, 'Make this the broadcast event — imports teams + bracket + queue'));
    }
    acts.appendChild(mk('btn btn-secondary btn-sm', 'Seeding', () => openSeedingStudio(ev), 'Open the seeding studio for this event — add teams by hand here'));
    if (platform === 'startgg') {
      acts.appendChild(mk('btn btn-secondary btn-sm', 'Pre-load teams', () => send('import_startgg_teams', { eventSlug: ev.eventSlug }), 'Import this event\'s entrants into your team library'));
      const refr = mk('btn btn-ghost btn-sm', '↻', () => { refr.disabled = true; refr.textContent = '…'; send('refresh_my_event', { id: ev.id }); setTimeout(() => { refr.disabled = false; refr.innerHTML = '↻'; }, 2500); }, 'Refresh this event from the platform now');
      acts.appendChild(refr);
      acts.appendChild(mk('btn btn-ghost btn-sm', 'View event ↗', () => window.open('https://www.start.gg/' + ev.eventSlug, '_blank', 'noopener'), 'Open on platform'));
    } else if (platform === 'challonge') {
      acts.appendChild(mk('btn btn-secondary btn-sm', 'Pre-load teams', () => send('import_challonge_teams', { slug: ev.platformSlug }), 'Import this tournament\'s participants into your team library'));
      acts.appendChild(mk('btn btn-ghost btn-sm', 'View event ↗', () => window.open('https://challonge.com/' + ev.platformSlug, '_blank', 'noopener'), 'Open on platform'));
    } else if (platform === 'manual' && ev.url) {
      acts.appendChild(mk('btn btn-ghost btn-sm', 'View event ↗', () => window.open(ev.url, '_blank', 'noopener'), 'Open the link you saved for this event'));
    }
    // NXGEN has no standalone "import by slug" or confirmed public tournament URL yet — Set
    // live/Seeding above still work; those two extra actions are start.gg/Challonge-only for now.

    // Platform-linking sub-row (push a start.gg event to a Challonge mirror for live score sync) —
    // only meaningful for a start.gg-sourced event; doesn't apply to an already-Challonge/NXGEN one.
    let linkRow = null;
    if (platform === 'startgg') {
      linkRow = document.createElement('div'); linkRow.className = 'me-linking';
      const isSynced = !!(ev.challongeSync && ev.challongeSync.slug);
      linkRow.style.display = isSynced ? 'flex' : 'none';   // auto-open when already linked
      const gear = mk('btn btn-ghost btn-sm me-gear', '⚙ Link platform', () => {
        const show = linkRow.style.display === 'none';
        linkRow.style.display = show ? 'flex' : 'none';
        gear.classList.toggle('is-on', show);
      }, 'Link / sync this event to another platform (Challonge)');
      gear.classList.toggle('is-on', isSynced);
      acts.appendChild(gear);

      linkRow.appendChild(mk('btn btn-blue btn-sm', 'Push / Sync to Challonge', () => openEvSyncModal(ev),
        'Full workflow: download start.gg data, map players via CSV, create/select a Challonge event, push seeding, keep scores synced live'));
      linkRow.appendChild(mk('btn btn-ghost btn-sm', 'Link existing', () => openChalLinkModal(ev), 'Link an existing Challonge tournament for real-time score sync'));
      if (isSynced) {
        const linkBadge = document.createElement('span');
        linkBadge.style.cssText = 'font-size:10px;padding:2px 7px;border-radius:3px;background:rgba(16,185,129,.15);color:#86efac;white-space:nowrap;cursor:default;align-self:center;';
        const errMark = ev.challongeSync.lastError ? ' !' : (ev.challongeSync.enabled ? '' : ' (paused)');
        linkBadge.textContent = `Synced: ${ev.challongeSync.slug}${errMark}`;
        if (ev.challongeSync.lastError) linkBadge.title = ev.challongeSync.lastError;
        linkRow.appendChild(linkBadge);
        const unlink = mk('btn btn-ghost btn-sm', 'Unlink', () => {
          if (unlink.dataset.armed) { send('unlink_event_challonge', { eventId: ev.id }); return; }
          unlink.dataset.armed = '1'; unlink.textContent = 'Confirm?'; setTimeout(() => { delete unlink.dataset.armed; unlink.textContent = 'Unlink'; }, 2400);
        }, 'Remove the real-time Challonge sync link for this event');
        linkRow.appendChild(unlink);
      }
    }

    const del = mk('btn btn-ghost btn-sm me-del', '✕', () => {
      if (del.dataset.armed) { send('remove_my_event', { id: ev.id }); return; }
      del.dataset.armed = '1'; del.textContent = 'Remove?'; setTimeout(() => { del.removeAttribute('data-armed'); del.textContent = '✕'; }, 2600);
    }, 'Remove from My Events');
    acts.appendChild(del);

    card.appendChild(acts);
    if (linkRow) card.appendChild(linkRow);
    list.appendChild(card);
  });
}
// Manual "+ Add Event" — a My Event with no platform behind it (a LAN, a one-off, anything not on
// start.gg/Challonge/NXGEN). No "Set live"/pre-load/auto-sync since there's no API to pull from;
// it's a plain reference you seed and manage by hand (Seeding tab already supports manual entry).
let _meAddLogo = '';
function meAddResetForm() {
  ['me-add-name', 'me-add-tournament', 'me-add-date', 'me-add-entrants', 'me-add-url'].forEach((id) => { const e = el(id); if (e) e.value = ''; });
  const g = el('me-add-game'); if (g) g.value = '';
  _meAddLogo = '';
  const lp = el('me-add-logo-preview'), le = el('me-add-logo-empty');
  if (lp) { lp.style.display = 'none'; lp.removeAttribute('src'); }
  if (le) le.style.display = '';
}
el('me-add-btn')?.addEventListener('click', () => {
  const form = el('me-add-form'); if (!form) return;
  const show = form.style.display === 'none';
  form.style.display = show ? '' : 'none';
  if (show) { const g = el('me-add-game'); if (g) lgGameOptions(g); el('me-add-name')?.focus(); }
});
el('me-add-cancel')?.addEventListener('click', () => {
  const form = el('me-add-form'); if (form) form.style.display = 'none';
  meAddResetForm();
});
el('me-add-logo-preview')?.addEventListener('click', () => el('me-add-logo-file')?.click());
el('me-add-logo-empty')?.addEventListener('click', () => el('me-add-logo-file')?.click());
el('me-add-logo-clear')?.addEventListener('click', () => {
  _meAddLogo = '';
  const lp = el('me-add-logo-preview'), le = el('me-add-logo-empty');
  if (lp) { lp.style.display = 'none'; lp.removeAttribute('src'); }
  if (le) le.style.display = '';
});
el('me-add-logo-file')?.addEventListener('change', async function () {
  const f = this.files && this.files[0]; this.value = ''; if (!f) return;
  try {
    _meAddLogo = await fileToBase64(f, 400);
    const lp = el('me-add-logo-preview'), le = el('me-add-logo-empty');
    if (lp) { lp.src = _meAddLogo; lp.style.display = ''; }
    if (le) le.style.display = 'none';
  } catch (e) { evStatus('Could not load logo.', 'err'); }
});
el('me-add-save')?.addEventListener('click', () => {
  const name = (el('me-add-name')?.value || '').trim();
  if (!name) { evStatus('Enter an event name.', 'err'); return; }
  const tournamentName = (el('me-add-tournament')?.value || '').trim();
  const game = el('me-add-game')?.value || '';
  const dateVal = el('me-add-date')?.value || '';
  const startAt = dateVal ? Math.floor(new Date(dateVal + 'T00:00:00').getTime() / 1000) : null;
  const numEntrants = Number(el('me-add-entrants')?.value) || 0;
  const url = (el('me-add-url')?.value || '').trim();
  send('add_my_event', {
    platform: 'manual', platformSlug: 'manual-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name, tournamentName, game, startAt, numEntrants, image: _meAddLogo, url,
  });
  el('me-add-form') && (el('me-add-form').style.display = 'none');
  meAddResetForm();
  evStatus(`Added "${name}" to MY EVENTS.`, 'ok');
});
// ── Cross-Platform Event Sync Modal ───────────────────────────────────────────

let _evSyncEvent = null;             // My Event being synced
let _evSyncMappings = {};            // name.toLowerCase() → challongeUsername from CSV upload
let _evSyncParticipants = [];        // resolved participant list (shown in preview)
let _evSyncChalTournaments = null;   // cached Challonge tournament list for the existing picker
let _evSyncChalSearchTimer = null;
let _evSyncLinkedSlug = '';          // slug selected from the existing-tournament picker

function openEvSyncModal(ev) {
  _evSyncEvent = ev;
  _evSyncMappings = {};
  _evSyncChalTournaments = null; // force fresh tournament list on open
  _evSyncLinkedSlug = (ev.challongeSync && ev.challongeSync.slug) || '';

  // Resolve participants from seeding studio data or roster
  _evSyncParticipants = resolveEvSyncParticipants(ev);

  // Pre-fill fields from event data
  const nameInp = el('ev-sync-t-name');
  const slugInp = el('ev-sync-t-slug');
  const gameInp = el('ev-sync-t-game');
  const titleEl = el('ev-sync-modal-title');

  if (titleEl) titleEl.textContent = `Push "${ev.name || 'Event'}" to Platform`;
  if (nameInp) nameInp.value = ev.name || '';
  if (slugInp) {
    const autoSlug = (ev.name || 'event').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 55);
    slugInp.value = autoSlug;
    evSyncUpdateSlugPreview(autoSlug);
  }
  if (gameInp) gameInp.value = ev.game || '';

  // Source info bar
  const srcEl = el('ev-sync-source-info');
  if (srcEl) {
    const n = _evSyncParticipants.length;
    const seeded = _evSyncParticipants.filter(p => p.seed).length;
    srcEl.innerHTML = `<strong style="color:var(--fg);">${escapeHtml(ev.name || '')}</strong>&nbsp;·&nbsp;start.gg&nbsp;·&nbsp;${n} participant${n !== 1 ? 's' : ''}${seeded ? `&nbsp;·&nbsp;${seeded} seeded` : ''}`;
  }

  // Select mode: switch to "existing" if this event already has a Challonge link
  if (_evSyncLinkedSlug) {
    const modeExisting = el('ev-sync-mode-existing');
    if (modeExisting) { modeExisting.checked = true; evSyncToggleMode('existing'); }
    // Pre-fill picker with the existing link
    const chalSearch = el('ev-sync-chal-search');
    if (chalSearch) chalSearch.value = _evSyncLinkedSlug;
    const chalClear = el('ev-sync-chal-clear');
    if (chalClear) chalClear.style.display = 'block';
    const selDiv = el('ev-sync-chal-selected');
    if (selDiv) {
      const sync = ev.challongeSync || {};
      const lastSync = sync.lastSyncAt ? ` · Last sync: ${new Date(sync.lastSyncAt).toLocaleTimeString()}` : '';
      const errPart = sync.lastError ? ` · Error: ${escapeHtml(sync.lastError)}` : '';
      selDiv.innerHTML = `Linked: <strong style="color:var(--fg);">challonge.com/${escapeHtml(_evSyncLinkedSlug)}</strong>${lastSync}${errPart}`;
      selDiv.style.display = '';
    }
    const autoSync = el('ev-sync-autosync');
    if (autoSync) autoSync.checked = !!(ev.challongeSync && ev.challongeSync.enabled);
  } else {
    const modeCreate = el('ev-sync-mode-create');
    if (modeCreate) { modeCreate.checked = true; evSyncToggleMode('create'); }
    const chalSearch = el('ev-sync-chal-search');
    if (chalSearch) chalSearch.value = '';
    const selDiv = el('ev-sync-chal-selected');
    if (selDiv) selDiv.style.display = 'none';
    const chalClear = el('ev-sync-chal-clear');
    if (chalClear) chalClear.style.display = 'none';
  }

  // Clear CSV status + log
  const csvSt = el('ev-sync-csv-status'); if (csvSt) csvSt.textContent = '';
  const logEl = el('ev-sync-log'); if (logEl) logEl.textContent = '';

  evSyncRenderPreview();
  el('ev-sync-modal').removeAttribute('hidden');
}

function resolveEvSyncParticipants(ev) {
  // Try seeding studio data first (has seedNum)
  const seedEntrants = ev.seeding && Array.isArray(ev.seeding.entrants) ? ev.seeding.entrants : [];
  if (seedEntrants.length > 0) {
    return seedEntrants
      .slice()
      .sort((a, b) => (a.seedNum || 9999) - (b.seedNum || 9999))
      .map((e, i) => ({
        name: e.name || '',
        seed: e.seedNum || (i + 1),
        players: (e.players || []).map(p => p.gamerTag).filter(Boolean)
      }));
  }
  // Fall back to roster
  const roster = Array.isArray(ev.roster) ? ev.roster : [];
  if (roster.length > 0) {
    return roster.map((t, i) => ({
      name: t.name || t.teamName || '',
      seed: i + 1,
      players: Array.isArray(t.players) ? t.players.map(p => p.gamerTag || p.name).filter(Boolean) : []
    }));
  }
  return [];
}

function evSyncToggleMode(mode) {
  const createFields   = el('ev-sync-create-fields');
  const existingFields = el('ev-sync-existing-fields');
  if (createFields)   createFields.style.display   = mode === 'create'   ? '' : 'none';
  if (existingFields) existingFields.style.display  = mode === 'existing' ? '' : 'none';
}

function evSyncUpdateSlugPreview(raw) {
  const clean = (raw || '').toLowerCase().replace(/[^a-z0-9_]/g, '_').replace(/__+/g, '_').replace(/^_|_$/g, '').slice(0, 60);
  const prev = el('ev-sync-slug-preview'); if (prev) prev.textContent = clean || '…';
}

function evSyncRenderPreview() {
  const label = el('ev-sync-preview-label');
  const container = el('ev-sync-preview');
  if (!container) return;
  const list = _evSyncParticipants;
  if (label) label.textContent = `Participants (${list.length})`;
  if (!list.length) {
    container.innerHTML = '<div style="font-size:12px; color:var(--muted); padding:6px;">No participants found — open Seeding or Pre-load Teams first to populate the list.</div>';
    return;
  }
  container.innerHTML = list.map((p, i) => {
    const mapped = _evSyncMappings[(p.name || '').toLowerCase()];
    const sub = p.players.length ? `<span style="color:var(--muted);">${p.players.slice(0,3).map(escapeHtml).join(', ')}${p.players.length>3?'…':''}</span>` : '';
    const userBadge = mapped ? `<span style="font-size:10px; padding:1px 6px; border-radius:3px; background:rgba(74,222,128,.15); color:#86efac; flex-shrink:0;">@${escapeHtml(mapped)}</span>` : '';
    return `<div style="display:flex; align-items:center; gap:8px; padding:3px 6px; border-radius:4px; background:rgba(255,255,255,.025);">
      <span style="font-size:10px; color:var(--muted); width:22px; text-align:right; flex-shrink:0;">${p.seed}</span>
      <span style="flex:1; font-size:12px; font-weight:600;">${escapeHtml(p.name)}</span>
      ${sub}
      ${userBadge}
    </div>`;
  }).join('');
}

// CSV parsing for username mapping
function parseEvSyncCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  if (!lines.length) return {};
  // Detect header
  const header = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/[^a-z0-9_]/g, ''));
  const nameIdx = header.findIndex(h => ['name','team','teamname','player','gamertag'].includes(h));
  const userIdx = header.findIndex(h => ['challonge_username','challongeusername','username','challonge'].includes(h));
  const map = {};
  const start = (nameIdx >= 0 && userIdx >= 0) ? 1 : 0; // skip header if detected
  for (let i = start; i < lines.length; i++) {
    const cols = lines[i].split(',').map(c => c.trim().replace(/^"|"$/g, ''));
    if (!cols.length || !cols[0]) continue;
    const ni = nameIdx >= 0 ? nameIdx : 0;
    const ui = userIdx >= 0 ? userIdx : 1;
    const name = (cols[ni] || '').trim();
    const username = (cols[ui] || '').trim();
    if (name && username) map[name.toLowerCase()] = username;
  }
  return map;
}

async function evSyncPush() {
  const logEl   = el('ev-sync-log');
  const pushBtn = el('ev-sync-push-btn');
  const setLog  = (msg, ok) => { if (logEl) { logEl.textContent = msg; logEl.style.color = ok === false ? '#f87171' : ok === true ? '#86efac' : 'var(--muted)'; } };

  const mode = document.querySelector('input[name="ev-sync-mode"]:checked')?.value || 'create';
  const startBracket = !!el('ev-sync-start-bracket')?.checked;

  if (!_evSyncParticipants.length) { setLog('No participants to push.', false); return; }
  if (!currentState.challonge?.hasKey) { setLog('Add your Challonge API key in Settings → Integrations first.', false); return; }

  if (pushBtn) { pushBtn.disabled = true; pushBtn.textContent = 'Pushing…'; }

  try {
    let slug;

    if (mode === 'create') {
      const name = (el('ev-sync-t-name')?.value || '').trim();
      const rawSlug = (el('ev-sync-t-slug')?.value || '').trim();
      const type = el('ev-sync-t-type')?.value || 'single elimination';
      const gameName = (el('ev-sync-t-game')?.value || '').trim();
      const isPrivate = !!el('ev-sync-t-private')?.checked;
      if (!name) throw new Error('Enter a tournament name.');
      if (!rawSlug) throw new Error('Enter a URL slug.');

      setLog('Creating tournament…', null);
      const cr = await fetch('http://localhost:3000/api/challonge/create-tournament', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, slug: rawSlug, tournamentType: type, gameName, private: isPrivate })
      }).then(r => r.json());
      if (!cr.ok) throw new Error(cr.error || 'Failed to create tournament');
      slug = cr.slug;
      setLog(`Tournament created: challonge.com/${slug}`, null);
    } else {
      // Use slug from the picker (preferred) or whatever is typed in the search input
      slug = _evSyncLinkedSlug || (el('ev-sync-chal-search')?.value || '').trim().replace(/^https?:\/\/[^/]*challonge\.com\//,'').replace(/\/$/, '');
      if (!slug) throw new Error('Select a tournament from the list first.');
    }

    const clearExisting = mode === 'existing' && !!el('ev-sync-clear-existing')?.checked;

    // Build participant payload with mappings
    const participants = _evSyncParticipants.map(p => ({
      name: p.name,
      seed: p.seed,
      challongeUsername: _evSyncMappings[(p.name || '').toLowerCase()] || null
    }));

    setLog(`Syncing ${participants.length} participants…`, null);
    // eventSlug lets the server override each seed with start.gg's TRUE bracket seed (initialSeedNum)
    // instead of trusting locally-cached roster/seeding-studio order, which can drift from what
    // actually produced the real bracket's bye placement.
    const sr = await fetch('http://localhost:3000/api/challonge/sync-participants', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tournamentSlug: slug, participants, clearExisting, eventSlug: _evSyncEvent && _evSyncEvent.eventSlug })
    }).then(r => r.json());
    // The route reports the real reason in .message (a summary) and .errors (per-chunk detail) —
    // it never sets .error, so checking only sr.error silently discarded the actual cause.
    const syncErrText = sr.message || (Array.isArray(sr.errors) && sr.errors.join('; ')) || sr.error || '';
    // Re-pushing to a tournament that already has its bracket started fails to (re-)add
    // participants — expected, not fatal. But the EXISTING bracket may have been seeded wrong
    // (e.g. from before this fix), producing a different shape than start.gg's real bracket, which
    // would silently block every result from matching. So actively REPAIR it: reset, re-apply the
    // true seed to every participant, and regenerate — rather than just skipping past the problem.
    const alreadySetUp = /no longer be added|already been taken|already exist/i.test(syncErrText);
    if (!sr.ok && !sr.added && !alreadySetUp) throw new Error(syncErrText || 'Sync failed (no detail returned)');

    if (alreadySetUp && _evSyncEvent && _evSyncEvent.eventSlug) {
      setLog('Bracket already started — repairing seeds & regenerating to match start.gg…', null);
      const rb = await fetch('http://localhost:3000/api/challonge/rebuild-bracket', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tournamentSlug: slug, eventSlug: _evSyncEvent.eventSlug })
      }).then(r => r.json());
      if (!rb.ok) throw new Error(rb.error || 'Failed to rebuild bracket');
      setLog(rb.message || 'Bracket rebuilt.', null);
    } else if (startBracket) {
      setLog('Generating bracket…', null);
      const br = await fetch('http://localhost:3000/api/challonge/start-bracket', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tournamentSlug: slug })
      }).then(r => r.json());
      // "Already started" is likewise non-fatal here (e.g. an existing tournament whose bracket
      // was generated outside this app) — fall through to the results backfill either way.
      if (!br.ok && !/already.*start|state/i.test(br.error || '')) throw new Error(br.error || 'Failed to start bracket');
    }

    // Backfill any COMPLETED start.gg results onto the Challonge bracket. For a finished PAST
    // event this fills in the entire bracket in one shot; for a future/current event with nothing
    // played yet it's a harmless no-op (results then flow live via the auto-sync link below).
    let resultsPushed = 0, pushWarn = '';
    if (_evSyncEvent && _evSyncEvent.eventSlug) {
      setLog('Pulling match results from start.gg…', null);
      try {
        const pr = await fetch('http://localhost:3000/api/challonge/push-results', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ tournamentSlug: slug, eventSlug: _evSyncEvent.eventSlug })
        }).then(r => r.json());
        if (pr.ok) {
          resultsPushed = pr.pushed || 0;
          if ((pr.unmatchedNames && pr.unmatchedNames.length) || (pr.unplaced && pr.unplaced.length)) pushWarn = pr.message || '';
        }
      } catch (e) { /* non-fatal — participants/bracket are already pushed */ }
    }

    // Link for live auto-sync. A freshly CREATED tournament is always linked (you built it to run it
    // live); for an EXISTING tournament, link only when the "keep synced" box is ticked.
    const autoSync = (mode === 'create') || (mode === 'existing' && !!el('ev-sync-autosync')?.checked);
    if (autoSync && _evSyncEvent && slug) {
      send('link_event_challonge', { eventId: _evSyncEvent.id, challongeSlug: slug, enabled: true });
    }

    const viewUrl = `https://challonge.com/${slug}`;
    const autoMsg = autoSync ? ' · Auto-sync enabled.' : '';
    const resMsg = resultsPushed ? ` · ${resultsPushed} result(s) filled in.` : '';
    const warnMsg = pushWarn ? ` — Heads up: ${pushWarn}` : '';
    setLog(`Done! ${sr.message || ''}${resMsg}${autoMsg}${warnMsg}`, pushWarn ? null : true);
    if (pushBtn) { pushBtn.textContent = 'View on Challonge ↗'; pushBtn.onclick = () => window.open(viewUrl, '_blank', 'noopener'); pushBtn.disabled = false; }
  } catch (e) {
    setLog(e.message, false);
    if (pushBtn) { pushBtn.disabled = false; pushBtn.textContent = 'Push to Challonge'; }
  }
}

// ── Challonge Link Modal — lightweight "just search, pick & link" ─────────────

let _chalLinkEvent = null;
let _chalLinkSlug = '';
let _chalLinkTournaments = null;
let _chalLinkSearchTimer = null;

function openChalLinkModal(ev) {
  _chalLinkEvent = ev;
  _chalLinkSlug = (ev.challongeSync && ev.challongeSync.slug) || '';
  _chalLinkTournaments = null;

  const titleEl = el('ev-chal-link-title');
  if (titleEl) titleEl.textContent = `Link Challonge: ${ev.name || 'Event'}`;

  const curDiv = el('ev-chal-link-current');
  if (curDiv) {
    if (_chalLinkSlug) { curDiv.textContent = `Currently linked: challonge.com/${_chalLinkSlug}`; curDiv.style.display = ''; }
    else curDiv.style.display = 'none';
  }

  const srch = el('ev-chal-link-search');
  if (srch) srch.value = '';
  const clr = el('ev-chal-link-clear');
  if (clr) clr.style.display = 'none';
  const res = el('ev-chal-link-results');
  if (res) res.style.display = 'none';
  const sel = el('ev-chal-link-selected');
  if (sel) sel.style.display = 'none';
  const logEl = el('ev-chal-link-log');
  if (logEl) logEl.textContent = '';
  const btn = el('ev-chal-link-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Link tournament'; }
  const commInp = el('ev-chal-link-community');
  if (commInp && !commInp.value) commInp.value = localStorage.getItem('ne_challonge_community') || '';

  el('ev-chal-link-modal').removeAttribute('hidden');
  setTimeout(() => el('ev-chal-link-search')?.focus(), 80);
}

function renderChalLinkDropdown(tournaments, filterQuery) {
  const container = el('ev-chal-link-results');
  if (!container) return;
  const filtered = filterQuery
    ? tournaments.filter(t => (t.name || '').toLowerCase().includes(filterQuery) || (t.slug || '').toLowerCase().includes(filterQuery))
    : tournaments;
  if (!filtered.length) {
    container.innerHTML = filterQuery
      ? `<div class="ev-dropdown-msg">No match for "${escapeHtml(filterQuery)}"</div>`
      : '<div class="ev-dropdown-msg">No Challonge tournaments found.</div>';
    container.style.display = 'block';
    return;
  }
  container.innerHTML = '';
  filtered.forEach(t => {
    const row = document.createElement('div');
    row.className = 'ev-dropdown-row';
    row.innerHTML = _chalTournamentRowHtml(t);
    row.addEventListener('click', () => {
      const si = el('ev-chal-link-search');
      if (si) si.value = t.name || t.slug;
      const cb = el('ev-chal-link-clear');
      if (cb) cb.style.display = 'block';
      container.style.display = 'none';
      _chalLinkSlug = t.slug || '';
      const selDiv = el('ev-chal-link-selected');
      if (selDiv) {
        const pCount = t.participantsCount ? ` · ${t.participantsCount} participants` : '';
        const stLabel = t.state ? ` · ${t.state}` : '';
        selDiv.innerHTML = `<strong style="color:var(--fg);">challonge.com/${escapeHtml(_chalLinkSlug)}</strong>${pCount}${stLabel}`;
        selDiv.style.display = '';
      }
      const btn = el('ev-chal-link-btn');
      if (btn) btn.disabled = false;
    });
    container.appendChild(row);
  });
  container.style.display = 'block';
}

(function wireChalLinkModal() {
  ['ev-chal-link-close', 'ev-chal-link-cancel'].forEach(id => {
    el(id)?.addEventListener('click', () => el('ev-chal-link-modal').setAttribute('hidden', ''));
  });
  el('ev-chal-link-modal')?.addEventListener('click', e => {
    if (e.target === el('ev-chal-link-modal')) el('ev-chal-link-modal').setAttribute('hidden', '');
  });

  const searchInput = el('ev-chal-link-search');
  const resultsDiv  = el('ev-chal-link-results');
  const clearBtn    = el('ev-chal-link-clear');
  if (!searchInput || !resultsDiv) return;

  async function loadLinkTournaments() {
    resultsDiv.innerHTML = '<div class="ev-dropdown-msg">Loading your Challonge tournaments…</div>';
    resultsDiv.style.display = 'block';
    try {
      const community = (el('ev-chal-link-community')?.value || '').trim();
      if (community) localStorage.setItem('ne_challonge_community', community);
      const subdomains = community ? [community] : [];
      const resp = await fetch('http://localhost:3000/api/challonge/my-tournaments', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ subdomains }) });
      const data = await resp.json();
      _chalLinkTournaments = resp.ok ? (data.tournaments || []) : [];
      renderChalLinkDropdown(_chalLinkTournaments, '');
      if (data.subdomainErrors?.length) {
        const errEl = el('ev-chal-link-results');
        if (errEl) errEl.insertAdjacentHTML('beforeend', data.subdomainErrors.map(e => `<div class="ev-dropdown-msg" style="color:#f59e0b;">Community "${escapeHtml(e.subdomain)}": ${escapeHtml(e.error)}</div>`).join(''));
      }
    } catch (e) {
      _chalLinkTournaments = [];
      resultsDiv.innerHTML = `<div class="ev-dropdown-msg" style="color:#ef4444;">Error: ${escapeHtml(e.message)}</div>`;
    }
  }

  // Restore saved community from localStorage
  const savedComm = localStorage.getItem('ne_challonge_community') || '';
  if (savedComm) { const ci = el('ev-chal-link-community'); if (ci) ci.value = savedComm; }

  el('ev-chal-link-community-reload')?.addEventListener('click', () => {
    _chalLinkTournaments = null;
    loadLinkTournaments();
  });

  searchInput.addEventListener('focus', () => {
    if (!currentState.challonge?.hasKey) {
      resultsDiv.innerHTML = '<div class="ev-dropdown-msg" style="color:#f59e0b;">Add a Challonge API key in Integrations first.</div>';
      resultsDiv.style.display = 'block';
      return;
    }
    if (_chalLinkTournaments !== null) {
      renderChalLinkDropdown(_chalLinkTournaments, searchInput.value.trim().toLowerCase());
      resultsDiv.style.display = 'block';
      return;
    }
    loadLinkTournaments();
  });

  searchInput.addEventListener('input', () => {
    const q = searchInput.value.trim();
    if (clearBtn) clearBtn.style.display = q ? 'block' : 'none';
    clearTimeout(_chalLinkSearchTimer);
    _chalLinkSearchTimer = setTimeout(() => {
      if (_chalLinkTournaments !== null) renderChalLinkDropdown(_chalLinkTournaments, q.toLowerCase());
    }, 60);
  });

  if (clearBtn) clearBtn.addEventListener('click', () => {
    searchInput.value = '';
    clearBtn.style.display = 'none';
    _chalLinkSlug = '';
    const selDiv = el('ev-chal-link-selected');
    if (selDiv) selDiv.style.display = 'none';
    const btn = el('ev-chal-link-btn');
    if (btn) btn.disabled = true;
    if (_chalLinkTournaments !== null) renderChalLinkDropdown(_chalLinkTournaments, '');
    searchInput.focus();
  });

  document.addEventListener('click', e => {
    if (!e.target.closest('#ev-chal-link-wrap') && !e.target.closest('#ev-chal-link-results')) {
      resultsDiv.style.display = 'none';
    }
  }, true);

  el('ev-chal-link-btn')?.addEventListener('click', () => {
    const btn   = el('ev-chal-link-btn');
    const logEl = el('ev-chal-link-log');
    const setLog = (msg, ok) => { if (logEl) { logEl.textContent = msg; logEl.style.color = ok === false ? '#f87171' : ok ? '#86efac' : 'var(--muted)'; } };
    if (!_chalLinkSlug || !_chalLinkEvent) { setLog('Select a tournament first.', false); return; }
    if (btn) { btn.disabled = true; btn.textContent = 'Linking…'; }
    setLog('Building participant map…', null);
    // Use a one-shot listener so we know when this specific link-result comes back
    const onMsg = (e2) => {
      try {
        const m = JSON.parse(e2.data);
        if (m.type !== 'link-result') return;
        ws.removeEventListener('message', onMsg);
        if (m.data.ok && !m.data.loading) {
          setLog(m.data.message || 'Linked!', true);
          const curDiv = el('ev-chal-link-current');
          if (curDiv) { curDiv.textContent = `Linked: challonge.com/${_chalLinkSlug}`; curDiv.style.display = ''; }
          if (btn) { btn.textContent = 'Linked'; }
          setTimeout(() => el('ev-chal-link-modal').setAttribute('hidden', ''), 1200);
        } else if (!m.data.ok) {
          setLog(m.data.message || 'Failed.', false);
          if (btn) { btn.disabled = false; btn.textContent = 'Link tournament'; }
        }
      } catch {}
    };
    ws.addEventListener('message', onMsg);
    send('link_event_challonge', { eventId: _chalLinkEvent.id, challongeSlug: _chalLinkSlug, enabled: true });
  });
})();

function _chalTournamentRowHtml(t) {
  const stateColors = { underway: '#10b981', pending: '#f59e0b', ended: '#9ca3af' };
  const stateBg     = { underway: 'rgba(16,185,129,0.15)', pending: 'rgba(245,158,11,0.15)', ended: 'rgba(107,114,128,0.2)' };
  const sc  = stateColors[t.state] || '#9ca3af';
  const sbg = stateBg[t.state]    || 'rgba(107,114,128,0.2)';
  const meta = [
    t.type ? t.type.replace(/_/g, ' ') : '',
    t.gameName || '',
    t.participantsCount ? `${t.participantsCount} teams` : '',
    t.subdomain ? `${t.subdomain}/…` : '',
  ].filter(Boolean).map(escapeHtml).join(' · ');
  // Letter avatar: first alphanumeric character, skip symbols like [$
  const letter = (((t.name || t.slug || '').match(/[A-Za-z0-9]/) || ['?'])[0]).toUpperCase();
  let hash = 0;
  for (let i = 0; i < (t.name || '').length; i++) hash = ((hash << 5) - hash + (t.name || '').charCodeAt(i)) | 0;
  const hue = Math.abs(hash) % 360;
  const avBg  = `hsl(${hue},45%,22%)`;
  const avClr = `hsl(${hue},70%,72%)`;
  const avatarHtml = `<div class="ev-dropdown-logo-ph" style="background:${avBg};color:${avClr};font-size:15px;font-weight:700;">${escapeHtml(letter)}</div>`;
  const logoHtml = t.logo
    ? `<img class="ev-dropdown-logo" src="${escapeHtml(t.logo)}" alt="" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">${avatarHtml.replace('style="', 'style="display:none;')}`
    : avatarHtml;
  return `${logoHtml}<div class="ev-dropdown-info"><div class="ev-dropdown-name">${escapeHtml(t.name || t.slug || '')}</div><div class="ev-dropdown-meta">${meta}</div></div><span class="ev-dropdown-badge" style="background:${sbg};color:${sc};text-transform:capitalize;">${escapeHtml(t.state || '')}</span>`;
}

function renderEvSyncChalDropdown(tournaments, filterQuery) {
  const container = el('ev-sync-chal-results');
  if (!container) return;
  const filtered = filterQuery
    ? tournaments.filter(t => (t.name || '').toLowerCase().includes(filterQuery) || (t.slug || '').toLowerCase().includes(filterQuery))
    : tournaments;
  if (!filtered.length) {
    container.innerHTML = filterQuery
      ? `<div class="ev-dropdown-msg">No match for "${escapeHtml(filterQuery)}"</div>`
      : '<div class="ev-dropdown-msg">No Challonge tournaments found.</div>';
    container.style.display = 'block';
    return;
  }
  container.innerHTML = '';
  filtered.forEach(t => {
    const row = document.createElement('div');
    row.className = 'ev-dropdown-row';
    row.innerHTML = _chalTournamentRowHtml(t);
    row.addEventListener('click', () => {
      const srch = el('ev-sync-chal-search');
      if (srch) srch.value = t.name || t.slug;
      const clr = el('ev-sync-chal-clear');
      if (clr) clr.style.display = 'block';
      container.style.display = 'none';
      _evSyncLinkedSlug = t.slug || '';
      const selDiv = el('ev-sync-chal-selected');
      if (selDiv) {
        const pCount = t.participantsCount ? ` · ${t.participantsCount} participants` : '';
        selDiv.innerHTML = `Selected: <strong style="color:var(--fg);">challonge.com/${escapeHtml(_evSyncLinkedSlug)}</strong>${pCount}`;
        selDiv.style.display = '';
      }
    });
    container.appendChild(row);
  });
  container.style.display = 'block';
}

// Wire up modal events (runs once on load)
(function wireEvSyncModal() {
  // Close buttons
  ['ev-sync-modal-close', 'ev-sync-modal-close2'].forEach(id => {
    el(id)?.addEventListener('click', () => el('ev-sync-modal').setAttribute('hidden', ''));
  });
  // Click outside to close
  el('ev-sync-modal')?.addEventListener('click', (e) => {
    if (e.target === el('ev-sync-modal')) el('ev-sync-modal').setAttribute('hidden', '');
  });

  // Mode toggle
  document.querySelectorAll('input[name="ev-sync-mode"]').forEach(r => {
    r.addEventListener('change', () => evSyncToggleMode(r.value));
  });

  // Slug live preview
  el('ev-sync-t-slug')?.addEventListener('input', () => evSyncUpdateSlugPreview(el('ev-sync-t-slug').value));

  // CSV upload
  el('ev-sync-csv-btn')?.addEventListener('click', () => el('ev-sync-csv-file')?.click());
  el('ev-sync-csv-file')?.addEventListener('change', (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev2) => {
      _evSyncMappings = parseEvSyncCsv(ev2.target.result || '');
      const n = Object.keys(_evSyncMappings).length;
      const st = el('ev-sync-csv-status');
      if (st) { st.textContent = n ? `${n} mapping${n !== 1 ? 's' : ''} loaded from CSV.` : 'No valid mappings found — check your CSV has name and challonge_username columns.'; st.style.color = n ? '#86efac' : '#f59e0b'; }
      evSyncRenderPreview();
    };
    reader.readAsText(file);
    e.target.value = '';
  });

  // Push button
  el('ev-sync-push-btn')?.addEventListener('click', evSyncPush);

  // Existing-tournament picker
  (function wireEvSyncChalPicker() {
    const searchInput = el('ev-sync-chal-search');
    const resultsDiv  = el('ev-sync-chal-results');
    const clearBtn    = el('ev-sync-chal-clear');
    if (!searchInput || !resultsDiv) return;

    async function loadEvSyncTournaments() {
      resultsDiv.innerHTML = '<div class="ev-dropdown-msg">Loading your Challonge tournaments…</div>';
      resultsDiv.style.display = 'block';
      try {
        const community = (el('ev-sync-chal-community')?.value || '').trim();
        if (community) localStorage.setItem('ne_challonge_community', community);
        const subdomains = community ? [community] : [];
        const resp = await fetch('http://localhost:3000/api/challonge/my-tournaments', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ subdomains }) });
        const data = await resp.json();
        _evSyncChalTournaments = resp.ok ? (data.tournaments || []) : [];
        renderEvSyncChalDropdown(_evSyncChalTournaments, '');
        if (data.subdomainErrors?.length) {
          const errEl = el('ev-sync-chal-results');
          if (errEl) errEl.insertAdjacentHTML('beforeend', data.subdomainErrors.map(e => `<div class="ev-dropdown-msg" style="color:#f59e0b;">Community "${escapeHtml(e.subdomain)}": ${escapeHtml(e.error)}</div>`).join(''));
        }
      } catch (e) {
        _evSyncChalTournaments = [];
        resultsDiv.innerHTML = `<div class="ev-dropdown-msg" style="color:#ef4444;">Error loading tournaments: ${escapeHtml(e.message)}</div>`;
      }
    }

    // Restore saved community
    const savedCommSync = localStorage.getItem('ne_challonge_community') || '';
    if (savedCommSync) { const ci = el('ev-sync-chal-community'); if (ci) ci.value = savedCommSync; }

    el('ev-sync-chal-community-reload')?.addEventListener('click', () => {
      _evSyncChalTournaments = null;
      loadEvSyncTournaments();
    });

    searchInput.addEventListener('focus', () => {
      if (!currentState.challonge?.hasKey) {
        resultsDiv.innerHTML = '<div class="ev-dropdown-msg" style="color:#f59e0b;">Add a Challonge API key in Integrations first.</div>';
        resultsDiv.style.display = 'block';
        return;
      }
      if (_evSyncChalTournaments !== null) {
        renderEvSyncChalDropdown(_evSyncChalTournaments, searchInput.value.trim().toLowerCase());
        resultsDiv.style.display = 'block';
        return;
      }
      loadEvSyncTournaments();
    });

    searchInput.addEventListener('input', () => {
      const q = searchInput.value.trim();
      if (clearBtn) clearBtn.style.display = q ? 'block' : 'none';
      clearTimeout(_evSyncChalSearchTimer);
      _evSyncChalSearchTimer = setTimeout(() => {
        if (_evSyncChalTournaments !== null) renderEvSyncChalDropdown(_evSyncChalTournaments, q.toLowerCase());
      }, 60);
    });

    if (clearBtn) clearBtn.addEventListener('click', () => {
      searchInput.value = '';
      clearBtn.style.display = 'none';
      _evSyncLinkedSlug = '';
      const selDiv = el('ev-sync-chal-selected');
      if (selDiv) selDiv.style.display = 'none';
      if (_evSyncChalTournaments !== null) renderEvSyncChalDropdown(_evSyncChalTournaments, '');
      searchInput.focus();
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('#ev-sync-chal-search-wrap') && !e.target.closest('#ev-sync-chal-results')) {
        resultsDiv.style.display = 'none';
      }
    }, true);
  })();
})();

// ── Seeding studio ───────────────────────────────────────────────────────────
// Funneled through My Events. Pull entrants + current seeds from start.gg (events you admin) OR
// import a CSV (outside TOs). Drag to reorder, sort, save onto the event, copy/export the list.
let _seedEvent = null;          // the My Events entry being seeded
let _seedRows = [];             // [{ entrantId, name, seedNum, players:[{gamerTag,rank,rankValue}], leaguePts }]
let _pendingCsvRows = null;     // CSV rows held while the column-mapping modal is open
let _seedDragIdx = -1;
let _seedLeagueId = '';         // optional league cross-reference (returning teams seed by points)
let _seedMode = 'rl-6mans';     // active rank system (per-event)
let _seedAgg = 'best';          // how a team's value aggregates its players: best | avg | sum
let _seedSortKey = 'rank';      // current order: rank | league | seed | name
let _seedTab = 'verified';      // active seeding tab: 'verified' | 'unverified'
let _seedUnvSort = 'unranked';  // unverified tab sort: 'unranked' | 'name'
let _seedUnvShowAll = false;    // when true, show all teams including verified ones

// Rank systems per title. kind 'num' = free number (MMR/Premier/Elo); 'tier' = named tiers + division.
const SEED_RANK_MODES = {
  // rl6mans ladder, worst→best (index = seed value, so higher index = better rank).
  'rl-6mans': { label: 'Rocket League · 6mans Ranks (S>X>A>B+>B>C>D>E>H)', kind: 'tier', nodiv: true, ph: 'e.g. A, B+, H', tiers: ['H', 'E', 'D', 'C', 'B', 'B+', 'A', 'X', 'S'] },
  'rl-mmr':   { label: 'Rocket League · 6mans MMR',               kind: 'num',  ph: 'MMR e.g. 1450' },
  'rl-tier':  { label: 'Rocket League · Ranked (standard)',        kind: 'tier', ph: 'e.g. Diamond II', tiers: ['Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Champion', 'Grand Champion', 'Supersonic Legend'] },
  'val':      { label: 'Valorant · Rank',           kind: 'tier', ph: 'e.g. Immortal 2', tiers: ['Iron', 'Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Ascendant', 'Immortal', 'Radiant'] },
  'cs2':      { label: 'CS2 · Premier rating',      kind: 'num',  ph: 'Premier e.g. 18500' },
  'ow':       { label: 'Overwatch 2 · Rank',        kind: 'tier', ph: 'e.g. Master 3', tiers: ['Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Master', 'Grandmaster', 'Champion'] },
  'apex':     { label: 'Apex Legends · Rank',       kind: 'tier', ph: 'e.g. Diamond 4', tiers: ['Rookie', 'Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Master', 'Apex Predator'] },
  'generic':  { label: 'Generic · number / Elo',    kind: 'num',  ph: 'number' },
};
function seedMode() { return SEED_RANK_MODES[_seedMode] || SEED_RANK_MODES.generic; }

// A team is "verified" when every player has a non-empty rank.
function isTeamVerified(row) {
  const ps = row.players || [];
  return ps.length > 0 && ps.every((p) => p.rank && p.rank.trim());
}

function seedUpdateTabCounts() {
  const vBtn = el('seed-tab-verified'), uvBtn = el('seed-tab-unverified');
  if (!vBtn || !uvBtn) return;
  const verified = _seedRows.filter((r) => isTeamVerified(r)).length;
  const unverified = _seedRows.length - verified;
  vBtn.textContent = 'Verified' + (_seedRows.length ? ` (${verified})` : '');
  uvBtn.textContent = 'Unverified' + (_seedRows.length ? ` (${unverified})` : '');
}

function seedSwitchTab(tab) {
  _seedTab = tab;
  const vPanel = el('seed-verified-panel'), uvPanel = el('seed-unverified-panel');
  const vBtn = el('seed-tab-verified'), uvBtn = el('seed-tab-unverified');
  if (vPanel)  vPanel.style.display  = tab === 'verified'   ? '' : 'none';
  if (uvPanel) uvPanel.style.display = tab === 'unverified' ? '' : 'none';
  if (vBtn)  vBtn.classList.toggle('active',  tab === 'verified');
  if (uvBtn) uvBtn.classList.toggle('active', tab === 'unverified');
  if (tab === 'unverified') { seedRenderUnverified(); }
}

// The rank string a lookup result yields under the current seed mode (single source of truth for
// both the "Use" buttons and the auto-apply in "Lookup All"). Returns null when nothing is usable.
function _6mUseRank(result) {
  if (!result || !result.found) return null;
  if (_seedMode === 'rl-6mans' || _seedMode === 'rl-tier') return result.rank || null;
  if (_seedMode === 'rl-mmr') return result.elo > 0 ? String(result.elo) : null;
  return null;
}
function _tgUseRank(result) {
  if (!result || !result.found) return null;
  if (_seedMode === 'rl-6mans') return result.sixmansTier || null;
  if (_seedMode === 'rl-mmr') return result.mmr != null ? String(Math.round(result.mmr)) : null;
  if (_seedMode === 'rl-tier') return result.rank || result.tier || null;
  return null;
}
// Build the rl6mans lookup result block for one player.
function build6mansResult(result, ti, pi) {
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
  if (!result || !result.found) {
    const msg = (result && result.error === 'not_found')
      ? 'Not on rl6mans.com — enter rank manually'
      : 'Not found — enter rank manually';
    return `<div class="seed-6m-result seed-6m-err">${msg}</div>`;
  }
  const useRank = _6mUseRank(result);
  const useBtn = useRank
    ? `<button class="btn btn-primary btn-xs seed-6m-use" data-ti="${ti}" data-pi="${pi}" data-rank="${esc(useRank)}">Use ${esc(useRank)}</button>`
    : '';
  return `<div class="seed-6m-result">
    <span class="seed-6m-rank">${esc(result.rank || 'Unranked')}</span>
    ${result.elo > 0 ? `<span class="seed-6m-elo">${result.elo} ELO</span>` : ''}
    ${result.region ? `<span class="seed-6m-region">${esc(result.region)}</span>` : ''}
    ${result.wins != null ? `<span class="seed-6m-record">${result.wins}W-${result.losses || 0}L</span>` : ''}
    ${useBtn}
  </div>`;
}

// Look up one player on rl6mans.com and store the result on the player object.
async function _6mansLookupPlayer(ti, pi, name) {
  const resp = await fetch('http://localhost:3000/api/rl6mans/profile', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  const data = await resp.json();
  const row = _seedRows[ti]; if (!row) return null;
  const p = row.players[pi]; if (!p) return null;
  p._6mResult = data.ok ? data.profile : { found: false, error: data.error || 'network' };
  return p._6mResult;
}

// Build the tracker.gg in-game rank result block.
function buildTGResult(result, ti, pi) {
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
  if (!result || !result.found) {
    const errMap = {
      not_found:      'Not found on tracker.gg',
      load_failed:    'Page failed to load',
      timeout:        'Timed out — try again',
      render_timeout: 'Rank data not found on page',
      no_rank:        'No ranked data on profile',
    };
    const msg = errMap[result && result.error] || 'Lookup failed — enter rank manually';
    return `<div class="seed-tg-result seed-tg-err">${msg}</div>`;
  }
  const useRank = _tgUseRank(result);
  const useBtn = useRank
    ? `<button class="btn btn-primary btn-xs seed-tg-use" data-ti="${ti}" data-pi="${pi}" data-rank="${esc(useRank)}">Use ${esc(useRank)}</button>`
    : '';
  return `<div class="seed-tg-result">
    <span class="seed-tg-tier">${esc(result.tier || '')}${result.division ? ' ' + esc(result.division) : ''}</span>
    ${result.mmr != null ? `<span class="seed-tg-mmr">${Math.round(result.mmr).toLocaleString()} MMR</span>` : ''}
    ${result.sixmansTier ? `<span class="seed-tg-6mmap">6mans: ${esc(result.sixmansTier)}</span>` : ''}
    ${useBtn}
  </div>`;
}

// Look up a player's in-game rank on tracker.gg via the in-app browser (no API key required).
async function _tgLookupByAccount(ti, pi, platform, username) {
  const resp = await fetch('http://localhost:3000/api/trackergg/lookup', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ platform, username }),
  });
  const data = await resp.json();
  const row = _seedRows[ti]; if (!row) return null;
  const p = row.players[pi]; if (!p) return null;
  p._tgResult = data;
  return data;
}

// Render the Unverified tab — fills #seed-unv-list only (sidebar is static HTML).
function seedRenderUnverified() {
  const panel = el('seed-unverified-panel');
  if (!panel || panel.style.display === 'none') return;
  const list = el('seed-unv-list'); if (!list) return;
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
  list.innerHTML = '';
  seedUpdateTabCounts();

  // Keep sort buttons in sync with state.
  panel.querySelectorAll('.seed-unv-sortbtn').forEach((b) => b.classList.toggle('active', b.dataset.unvsort === _seedUnvSort));
  const showAllBtn = el('seed-unv-showall-btn');
  if (showAllBtn) showAllBtn.classList.toggle('is-on', _seedUnvShowAll);

  // Build display rows.
  let rows = _seedRows.map((row, ti) => ({ row, ti }));
  if (!_seedUnvShowAll) rows = rows.filter(({ row }) => !isTeamVerified(row));

  if (!rows.length) {
    list.innerHTML = `<div class="seed-empty">${_seedUnvShowAll ? 'No teams loaded yet.' : 'All teams are verified — every player has a rank.'}</div>`;
    return;
  }

  // Sort.
  if (_seedUnvSort === 'name') {
    rows.sort((a, b) => (a.row.name || '').localeCompare(b.row.name || ''));
  } else {
    rows.sort((a, b) => {
      const ua = (a.row.players || []).filter((p) => !p.rank || !p.rank.trim()).length;
      const ub = (b.row.players || []).filter((p) => !p.rank || !p.rank.trim()).length;
      return ub - ua;
    });
  }

  const mode = seedMode();
  let listId = '';
  if (mode.kind === 'tier' && mode.tiers) {
    listId = 'seed-unv-tier-opts';
    let dl = document.getElementById(listId);
    if (!dl) { dl = document.createElement('datalist'); dl.id = listId; list.appendChild(dl); }
    const opts = mode.nodiv ? mode.tiers.slice() : mode.tiers.flatMap((t) => ['III', 'II', 'I'].map((d) => `${t} ${d}`));
    dl.innerHTML = opts.map((o) => `<option value="${esc(o)}">`).join('');
  }

  rows.forEach(({ row, ti }) => {
    const card = document.createElement('div');
    card.className = 'seed-team';
    const unvCount = (row.players || []).filter((p) => !p.rank || !p.rank.trim()).length;
    const statusBadge = unvCount === 0
      ? `<span class="seed-unv-verified-badge">Verified</span>`
      : `<span class="seed-unv-badge">${unvCount} unranked</span>`;
    const head = `<div class="seed-team-head">
      <span class="seed-num">${ti + 1}</span>
      <div class="seed-team-name">${esc(row.name) || '(unnamed)'}</div>
      ${statusBadge}
    </div>`;

    const playersHtml = (row.players || []).map((p, pi) => {
      const isRanked = p.rank && p.rank.trim();
      // Tracker.gg lookup row — pre-filled with the player's known Epic/Steam account. start.gg hides
      // OTHER players' connected accounts (its `authorizations` field is self-only), so epic/steam are
      // usually empty; fall back to the gamertag as the Epic username — for RL it's almost always the
      // player's Epic display name — so the row is ready to look up (and editable) instead of blank.
      const tgPlt = p.epic ? 'epic' : p.steam ? 'steam' : 'epic';
      const tgUsr = esc(p.epic || p.steam || p.gamerTag || '');
      const tgRowHtml = `<div class="seed-tg-row">
        <select class="seed-tg-plat-sel">
          <option value="epic"${tgPlt === 'epic' ? ' selected' : ''}>epic</option>
          <option value="steam"${tgPlt === 'steam' ? ' selected' : ''}>steam</option>
          <option value="psn">psn</option>
          <option value="xbl">xbl</option>
          <option value="switch">switch</option>
        </select>
        <input class="input-text seed-tg-id-inp" value="${tgUsr}" placeholder="username">
        <button class="btn btn-ghost btn-xs seed-tg-rank-btn" data-ti="${ti}" data-pi="${pi}" title="Look up in-game rank on tracker.gg">Rank</button>
      </div>`;
      const m6ResultHtml = p._6mResult ? build6mansResult(p._6mResult, ti, pi) : '';
      const tgResultHtml = p._tgResult ? buildTGResult(p._tgResult, ti, pi) : '';
      return `<div class="seed-unv-player${isRanked ? ' seed-unv-player-ranked' : ''}" data-ti="${ti}" data-pi="${pi}">
        <div class="seed-unv-player-top">
          <span class="seed-ptag">${esc(p.gamerTag) || '(player)'}</span>
          <input class="input-text seed-prank seed-unv-prank" data-ti="${ti}" data-pi="${pi}"
            value="${esc(p.rank)}" placeholder="${esc(mode.ph || 'rank')}"${listId ? ` list="${listId}"` : ''}
            title="Enter rank manually">
          <button class="btn btn-ghost btn-xs seed-6m-lookup" data-ti="${ti}" data-pi="${pi}" data-name="${esc(p.gamerTag)}" title="Look up on rl6mans.com">6mans</button>
        </div>
        ${tgRowHtml}
        ${m6ResultHtml}
        ${tgResultHtml}
      </div>`;
    }).join('');

    card.innerHTML = head + `<div class="seed-players-wrap">${playersHtml}</div>`;
    list.appendChild(card);
  });

  // Rank inputs — immediate edit without going to verified tab.
  list.querySelectorAll('.seed-unv-prank').forEach((inp) => {
    inp.addEventListener('mousedown', (e) => e.stopPropagation());
    inp.addEventListener('change', function () {
      const ti = +this.dataset.ti, pi = +this.dataset.pi;
      const row = _seedRows[ti]; if (!row) return;
      const p = row.players[pi]; if (!p) return;
      p.rank = this.value.trim();
      p.rankValue = seedRankValue(p.rank, _seedMode);
      seedRecomputeValues();
      const playerDiv = this.closest('.seed-unv-player');
      if (playerDiv) playerDiv.classList.toggle('seed-unv-player-ranked', !!p.rank);
      const card2 = this.closest('.seed-team');
      if (card2) {
        const badge = card2.querySelector('.seed-unv-badge, .seed-unv-verified-badge');
        const unvLeft = (row.players || []).filter((pp) => !pp.rank || !pp.rank.trim()).length;
        if (badge) {
          if (unvLeft === 0) { badge.className = 'seed-unv-verified-badge'; badge.textContent = 'Verified'; }
          else { badge.className = 'seed-unv-badge'; badge.textContent = unvLeft + ' unranked'; }
        }
      }
      seedUpdateTabCounts();
    });
  });

  // Per-player 6mans lookup buttons.
  list.querySelectorAll('.seed-6m-lookup').forEach((btn) => {
    btn.addEventListener('click', async function () {
      const ti = +this.dataset.ti, pi = +this.dataset.pi, name = this.dataset.name;
      this.disabled = true; this.textContent = '...';
      try {
        await _6mansLookupPlayer(ti, pi, name);
        seedRenderUnverified();
      } catch (e) {
        this.disabled = false; this.textContent = '6mans';
        seedStatus('6mans lookup failed: ' + (e.message || 'network error'), 'err');
      }
    });
  });

  // Use buttons — apply 6mans looked-up rank.
  list.querySelectorAll('.seed-6m-use').forEach((btn) => {
    btn.addEventListener('click', function () {
      const ti = +this.dataset.ti, pi = +this.dataset.pi, rank = this.dataset.rank;
      const row = _seedRows[ti]; if (!row) return;
      const p = row.players[pi]; if (!p) return;
      p.rank = rank; p.rankValue = seedRankValue(rank, _seedMode);
      seedRecomputeValues();
      seedRenderUnverified();
      seedRender();
    });
  });

  // Rank buttons — tracker.gg in-game rank lookup (reads platform + username from the row's inputs).
  list.querySelectorAll('.seed-tg-rank-btn').forEach((btn) => {
    btn.addEventListener('click', async function () {
      const ti = +this.dataset.ti, pi = +this.dataset.pi;
      const row2 = this.closest('.seed-tg-row');
      const platform = row2 ? (row2.querySelector('.seed-tg-plat-sel') || {}).value || 'epic' : 'epic';
      const username = (row2 ? (row2.querySelector('.seed-tg-id-inp') || {}).value : '') || '';
      if (!username.trim()) { seedStatus('Enter a username first.', 'warn'); return; }
      this.disabled = true; this.textContent = '...';
      try {
        await _tgLookupByAccount(ti, pi, platform, username.trim());
        seedRenderUnverified();
      } catch (e) {
        this.disabled = false; this.textContent = 'Rank';
        seedStatus('tracker.gg lookup failed: ' + (e.message || 'network error'), 'err');
      }
    });
  });

  // Persist tracker.gg account edits onto the player (p.epic / p.steam) so a corrected username or
  // platform survives the frequent re-renders (every 6mans lookup re-renders the list) and is saved
  // with the seeding. Without this, an edit would revert to the gamertag pre-fill on the next render.
  list.querySelectorAll('.seed-tg-row').forEach((rowEl) => {
    const wrap = rowEl.closest('.seed-unv-player'); if (!wrap) return;
    const ti = +wrap.dataset.ti, pi = +wrap.dataset.pi;
    const inp = rowEl.querySelector('.seed-tg-id-inp');
    const sel = rowEl.querySelector('.seed-tg-plat-sel');
    const persist = () => {
      const p = _seedRows[ti] && _seedRows[ti].players[pi]; if (!p) return;
      const plat = (sel && sel.value) || 'epic';
      const v = (inp && inp.value.trim()) || '';
      if (plat === 'steam') p.steam = v; else if (plat === 'epic') p.epic = v;
    };
    if (inp) { inp.addEventListener('mousedown', (e) => e.stopPropagation()); inp.addEventListener('change', persist); }
    if (sel) sel.addEventListener('change', persist);
  });

  // Use buttons — apply tracker.gg looked-up rank.
  list.querySelectorAll('.seed-tg-use').forEach((btn) => {
    btn.addEventListener('click', function () {
      const ti = +this.dataset.ti, pi = +this.dataset.pi, rank = this.dataset.rank;
      const row = _seedRows[ti]; if (!row) return;
      const p = row.players[pi]; if (!p) return;
      p.rank = rank; p.rankValue = seedRankValue(rank, _seedMode);
      seedRecomputeValues();
      seedRenderUnverified();
      seedRender();
    });
  });

  // Lookup All button — look up every unranked player on rl6mans.com.
  const lookupAllBtn = el('seed-unv-lookup-all');
  if (lookupAllBtn) {
    const newBtn = lookupAllBtn.cloneNode(true);
    lookupAllBtn.replaceWith(newBtn);
    newBtn.addEventListener('click', async function () {
      const targets = [];
      rows.forEach(({ row, ti }) => {
        (row.players || []).forEach((p, pi) => {
          if (!p.rank || !p.rank.trim()) targets.push({ ti, pi, name: p.gamerTag });
        });
      });
      if (!targets.length) { seedStatus('No unranked players to look up.', 'info'); return; }
      const statusEl = el('seed-unv-lookup-status');
      this.disabled = true;
      const stillUnranked = () => targets.filter((t) => {
        const p = _seedRows[t.ti] && _seedRows[t.ti].players[t.pi];
        return p && (!p.rank || !p.rank.trim());
      });
      const apply = (t, useRank) => {
        const p = _seedRows[t.ti] && _seedRows[t.ti].players[t.pi];
        if (p && useRank) { p.rank = useRank; p.rankValue = seedRankValue(useRank, _seedMode); return true; }
        return false;
      };
      let got6m = 0, gotTg = 0;

      // Pass 1 — rl6mans.com by gamertag. Confident hits auto-apply (the profile is an exact-tag match).
      this.textContent = `rl6mans 0/${targets.length}`;
      if (statusEl) { statusEl.style.display = ''; statusEl.textContent = `rl6mans 0 / ${targets.length}`; }
      let d1 = 0;
      for (const t of targets) {
        try { if (apply(t, _6mUseRank(await _6mansLookupPlayer(t.ti, t.pi, t.name)))) got6m++; } catch (_) {}
        d1++;
        this.textContent = `rl6mans ${d1}/${targets.length}`;
        if (statusEl) statusEl.textContent = `rl6mans ${d1} / ${targets.length}`;
      }

      // Pass 2 — tracker.gg fallback for anyone still unranked, using the pre-filled account
      // (Epic = gamertag by default). Best-effort: a gamertag that isn't the player's Epic won't match.
      const left = stillUnranked();
      if (left.length) {
        let d2 = 0;
        for (const t of left) {
          const p = _seedRows[t.ti] && _seedRows[t.ti].players[t.pi];
          if (p) {
            const platform = p.epic ? 'epic' : p.steam ? 'steam' : 'epic';
            const username = (p.epic || p.steam || p.gamerTag || '').trim();
            if (username) {
              try { if (apply(t, _tgUseRank(await _tgLookupByAccount(t.ti, t.pi, platform, username)))) gotTg++; } catch (_) {}
            }
          }
          d2++;
          this.textContent = `tracker.gg ${d2}/${left.length}`;
          if (statusEl) statusEl.textContent = `tracker.gg ${d2} / ${left.length}`;
        }
      }

      this.disabled = false; this.textContent = 'Lookup All';
      if (statusEl) statusEl.style.display = 'none';
      seedRecomputeValues();
      seedRenderUnverified();
      seedRender();
      const remaining = stillUnranked().length;
      const parts = [`${got6m} from rl6mans`];
      if (gotTg) parts.push(`${gotTg} from tracker.gg`);
      seedStatus(`Auto-ranked ${parts.join(' + ')}` + (remaining ? ` · ${remaining} still need a manual rank` : ' · every player ranked'), remaining ? 'warn' : 'ok');
    });
  }
}
// Best default rank system for a game id/name.
function seedDefaultMode(game) {
  const g = (game || '').toString().toLowerCase();
  if (/rocket|\brl\b/.test(g)) return 'rl-6mans';
  if (/valorant/.test(g)) return 'val';
  if (/cs2|counter|cs:?go/.test(g)) return 'cs2';
  if (/overwatch/.test(g)) return 'ow';
  if (/apex/.test(g)) return 'apex';
  return 'generic';
}
// Parse one rank string → numeric value (higher = better) under the active mode. null if blank/unknown.
function seedRankValue(str, modeKey) {
  const mode = SEED_RANK_MODES[modeKey] || SEED_RANK_MODES.generic;
  const s = (str || '').toString().trim().toLowerCase();
  if (!s) return null;
  const num = parseFloat(s.replace(/[^0-9.]/g, ''));
  if (mode.kind === 'num') return Number.isFinite(num) ? num : null;
  // tier: tier index (1-based) * 10 + division (I/II/III or 1..5); plain numbers still pass through.
  const tiers = mode.tiers || [];
  let ti = 0;
  for (let i = 0; i < tiers.length; i++) { if (s.includes(tiers[i].toLowerCase())) ti = Math.max(ti, i + 1); }
  if (!ti) return Number.isFinite(num) ? num : null;   // unknown tier word → any trailing number
  const roman = (s.match(/\biii\b|\bii\b|\bi\b/) || [''])[0];
  const digit = (s.match(/\b([1-5])\b/) || [, ''])[1];
  const div = { iii: 3, ii: 2, i: 1 }[roman] || (digit ? parseInt(digit, 10) : 0);
  return ti * 10 + div;
}
// A team's seed value from its players' ranks, under the active aggregation (best | avg | sum).
// For avg: divide by ALL players (not just ranked ones) so teams with unranked players sort lower.
function seedTeamValue(row) {
  const ps = row.players || [];
  const vals = ps.map((p) => p.rankValue).filter((v) => v != null && Number.isFinite(v));
  if (!vals.length) return null;
  if (_seedAgg === 'sum') return vals.reduce((a, b) => a + b, 0);
  if (_seedAgg === 'avg') {
    const total = ps.length || 1;
    return Math.round((vals.reduce((a, b) => a + b, 0) / total) * 10) / 10;
  }
  return Math.max(...vals);   // best player (default)
}
// Re-derive every player's rankValue under the current mode (after a mode change / import).
function seedRecomputeValues() {
  _seedRows.forEach((row) => (row.players || []).forEach((p) => { p.rankValue = seedRankValue(p.rank, _seedMode); }));
}
function seedAggLabel() { return _seedAgg === 'sum' ? 'Sum of players' : _seedAgg === 'avg' ? 'Average of players' : 'Best player'; }
// Update the topbar chip (team/player count) and connection dot.
function seedUpdateHeader() {
  const chip = el('seed-team-chip');
  const dot  = el('seed-conn-dot');
  if (chip) {
    if (_seedRows.length) {
      const players = _seedRows.reduce((s, r) => s + (r.players || []).length, 0);
      chip.textContent = `${_seedRows.length} teams · ${players} players`;
      chip.removeAttribute('hidden');
    } else {
      chip.setAttribute('hidden', '');
    }
  }
  if (dot) {
    const hasToken = !!(currentState.startgg && currentState.startgg.hasToken);
    dot.className = 'seed-conn-dot ' + (hasToken ? 'ok' : 'err');
    dot.title = hasToken ? 'start.gg connected' : 'No start.gg API token — add one in Settings → Integrations';
  }
}
// Returns a human-readable label for the team badge.
// tier+best → rank string of the top player ("A+"); tier+avg+nodiv → nearest tier ("~B+"); else number.
function seedTeamDisplay(row) {
  const tv = seedTeamValue(row);
  if (tv == null) return null;
  const mode = seedMode();
  if (mode.kind === 'tier') {
    if (_seedAgg === 'best') {
      const best = (row.players || []).find((p) => p.rankValue === tv);
      if (best && best.rank) return best.rank.toUpperCase();
    } else if (_seedAgg === 'avg' && mode.nodiv && mode.tiers) {
      let closest = null, closestDist = Infinity;
      mode.tiers.forEach((t, i) => { const d = Math.abs((i + 1) * 10 - tv); if (d < closestDist) { closestDist = d; closest = t; } });
      if (closest) return '~' + closest.toUpperCase();
    }
  }
  return tv;
}

function seedPopulateLeagues() {
  const sel = el('seed-league'); if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = '<option value="">No league</option>' + (currentState.leagues || [])
    .map((l) => `<option value="${l.id}">${(l.name || 'League').replace(/</g, '&lt;')}</option>`).join('');
  sel.value = cur || _seedLeagueId || '';
}
function seedPopulateModes() {
  const sel = el('seed-rankmode'); if (!sel) return;
  sel.innerHTML = Object.keys(SEED_RANK_MODES).map((k) => `<option value="${k}">${SEED_RANK_MODES[k].label}</option>`).join('');
  sel.value = _seedMode;
}
function leaguePointsByName(league, name) {
  if (!league) return null;
  const key = (name || '').trim().toLowerCase();
  const team = (league.teams || []).find((t) => (t.name || '').trim().toLowerCase() === key);
  if (!team) return null;                       // not in the league → a new team
  const st = (league.standings || []).find((s) => s.teamId === team.id);
  return st ? (st.pts || 0) : 0;                 // in the league but no standings yet → 0 pts
}
function seedApplyLeague() {
  _seedLeagueId = el('seed-league')?.value || '';
  const league = (currentState.leagues || []).find((l) => l.id === _seedLeagueId) || null;
  _seedRows.forEach((r) => { r.leaguePts = league ? leaguePointsByName(league, r.name) : null; });

  const sortBtn   = el('seed-sort-league');
  const summaryEl = el('seed-league-summary');
  if (sortBtn) sortBtn.style.display = league ? '' : 'none';

  if (league) {
    const returning = _seedRows.filter((r) => r.leaguePts != null);
    const newCount  = _seedRows.length - returning.length;
    const topThree  = [...returning].sort((a, b) => (b.leaguePts || 0) - (a.leaguePts || 0)).slice(0, 3);
    if (summaryEl) {
      summaryEl.style.display = '';
      summaryEl.innerHTML =
        `<strong style="color:var(--text);">${returning.length}</strong> returning &nbsp;·&nbsp; <strong style="color:var(--text);">${newCount}</strong> new<br>` +
        topThree.map((r) => `${tlEsc(r.name)} <span style="opacity:.6">${r.leaguePts} pts</span>`).join('<br>');
    }
    seedSort('league');
    seedStatus(`${returning.length} returning from "${league.name}" seeded by points — ${newCount} new team(s) follow by rank.`, 'ok');
  } else {
    if (summaryEl) summaryEl.style.display = 'none';
    seedRender();
  }
}

function seedStatus(msg, kind) {
  const s = el('seed-status'); if (!s) return;
  s.textContent = msg || ''; s.style.color = kind === 'err' ? '#f56565' : (kind === 'ok' ? '#9ae6b4' : 'var(--muted)');
}
// Seeding is its own ESPORTS sub-tab. The panel shows EITHER the event picker (#seed-pick) or the
// studio (#seeding-studio, relocated into #seed-studio-host at load).
function seedShowStudio(on) {
  const studio = el('seeding-studio'), pick = el('seed-pick');
  if (studio) studio.style.display = on ? '' : 'none';
  if (pick) pick.style.display = on ? 'none' : '';
}
// Switch the ESPORTS subnav to a given tab (drives panel visibility via the #ev-subnav handler).
function evSelectTab(tab) {
  const btn = document.querySelector(`#ev-subnav .ev-subnav-btn[data-evtab="${tab}"]`);
  if (btn) btn.click();
}
// Picker inside the Seeding tab — lists saved events; click one to seed it.
function renderSeedPicker() {
  const list = el('seed-pick-list'); if (!list) return;
  const empty = el('seed-pick-empty');
  const events = currentState.myEvents || [];
  if (empty) empty.style.display = events.length ? 'none' : '';
  list.innerHTML = '';
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
  events.forEach((ev) => {
    const card = document.createElement('div'); card.className = 'my-event-card';
    const rosterN = Array.isArray(ev.roster) ? ev.roster.length : (ev.numEntrants || 0);
    const sub = [ev.game, rosterN ? rosterN + ' teams' : '', ev.tournamentName].filter(Boolean).join(' · ');
    const seeded = !!(ev.seeding && Array.isArray(ev.seeding.entrants) && ev.seeding.entrants.length);
    card.innerHTML = evCardLogo(ev) + `<div class="me-info"><div class="me-name">${esc(ev.name || 'Event')}${seeded ? ` <span class="me-live" style="background:#3b82f6;">${ev.seeding.entrants.length} SEEDED</span>` : ''}</div>`
      + `<div class="me-sub">${esc(sub)}</div><div class="me-meta">${evSyncBadge(ev)}</div></div>`;
    const acts = document.createElement('div'); acts.className = 'me-acts';
    const b = document.createElement('button'); b.className = 'btn btn-primary btn-sm';
    b.textContent = seeded ? 'Edit seeding' : 'Seed event';
    b.addEventListener('click', () => openSeedingStudio(ev));
    acts.appendChild(b); card.appendChild(acts); list.appendChild(card);
  });
}
// Re-render the My Events list / seeding picker when a background sync changes something — but only
// when actually visible and only on a real change (cheap signature), so it never churns the UI.
let _evMySig = '';
function evLiveRefreshOpen() {
  const evs = currentState.myEvents || [];
  const sig = evs.map((e) => `${e.id}:${e.lastSync || 0}:${(e.roster || []).length}:${e.syncError ? 1 : 0}:${e.seeding ? (e.seeding.entrants || []).length : 0}`).join('|');
  if (sig === _evMySig) return;
  _evMySig = sig;
  const me = el('ev-myevents-panel'); if (me && me.offsetParent !== null) renderMyEvents();
  const pick = el('seed-pick'); if (pick && pick.offsetParent !== null) renderSeedPicker();
}
function openSeedingStudio(ev) {
  evSelectTab('seeding');   // jump to the Seeding tab (no-op if already there)
  // Re-resolve to the live My Events entry (so we save by id).
  _seedEvent = (currentState.myEvents || []).find((e) => e.id === ev.id || e.eventSlug === ev.eventSlug) || ev;
  el('seed-title').textContent = 'Seeding — ' + (_seedEvent.name || 'event');
  seedShowStudio(true);
  _seedUnvSort = 'unranked'; _seedUnvShowAll = false;
  seedSwitchTab('verified');
  seedUpdateHeader();
  // Restore per-event config (rank system + aggregation), else infer from the game.
  const sd = _seedEvent.seeding || {};
  _seedMode = (sd.rankMode && SEED_RANK_MODES[sd.rankMode]) ? sd.rankMode : seedDefaultMode(_seedEvent.game);
  _seedAgg = ['best', 'avg', 'sum'].includes(sd.agg) ? sd.agg : (_seedMode === 'rl-6mans' ? 'avg' : 'best');
  _seedSortKey = 'rank';
  seedPopulateModes(); seedPopulateLeagues();
  const am = el('seed-aggmethod'); if (am) am.value = _seedAgg;
  if (Array.isArray(sd.entrants) && sd.entrants.length) {
    _seedRows = sd.entrants.map((x) => ({
      entrantId: x.entrantId || '', name: x.name || '', seedNum: x.seedNum || null,
      players: (x.players || []).map((p) => ({
        gamerTag: p.gamerTag || '', rank: p.rank || '', rankValue: null,
        epic: p.epic || '', steam: p.steam || '', alts: Array.isArray(p.alts) ? p.alts : [],
        startggSlug: p.startggSlug || null, startggPlayerId: p.startggPlayerId || null,
      })),
      leaguePts: null,
    }));
    seedRecomputeValues();
    seedApplyLeague();
    seedMergeRoster(_seedEvent.roster);   // fold in any newly-registered teams from the live refresh
  } else if (Array.isArray(_seedEvent.roster) && _seedEvent.roster.length) {
    seedFromRoster(_seedEvent.roster);
    seedStatus(`${_seedRows.length} teams loaded live from start.gg. Add player ranks, then seed.`, 'ok');
  } else {
    _seedRows = []; seedRender(); seedLoadStartgg();
  }
}
// Build seed rows from a live roster ([{entrantId,name,seedNum,players:[{gamerTag}]}]).
function seedFromRoster(roster) {
  _seedRows = (roster || []).map((e) => ({
    entrantId: e.entrantId || '', name: e.name || '', seedNum: e.seedNum || null,
    players: (e.players || []).map((p) => ({ gamerTag: p.gamerTag || '', rank: '', rankValue: null,
      epic: p.epic || '', steam: p.steam || '', alts: p.alts || [],
      startggSlug: p.startggSlug || null, startggPlayerId: p.startggPlayerId || null })),
    leaguePts: null, perfScore: null,
  }));
  if (_seedLeagueId) seedApplyLeague(); else seedRender();
}
// Add roster teams not already present (by entrantId or name), preserving existing ranks.
function seedMergeRoster(roster) {
  if (!Array.isArray(roster) || !roster.length) { seedRender(); return; }
  const have = new Set(_seedRows.map((r) => r.entrantId || ('n:' + (r.name || '').toLowerCase())));
  let added = 0;
  roster.forEach((e) => {
    const key = e.entrantId || ('n:' + (e.name || '').toLowerCase());
    if (have.has(key)) return;
    _seedRows.push({ entrantId: e.entrantId || '', name: e.name || '', seedNum: e.seedNum || null,
      players: (e.players || []).map((p) => ({ gamerTag: p.gamerTag || '', rank: '', rankValue: null,
        epic: p.epic || '', steam: p.steam || '', alts: p.alts || [],
        startggSlug: p.startggSlug || null, startggPlayerId: p.startggPlayerId || null })),
      leaguePts: null, perfScore: null });
    added++;
  });
  seedStatus(added ? `Loaded saved seeding + ${added} newly-registered team(s).` : 'Loaded your saved seeding.');
  seedRender();
}
async function seedLoadStartgg() {
  if (!_seedEvent) return;
  if (!currentState.startgg?.hasToken) { seedStatus('No start.gg API token — add one in Settings → Integrations.', 'err'); return; }
  const btn = el('seed-load-startgg'); if (btn) { btn.disabled = true; btn.textContent = 'Pulling…'; }
  seedStatus('Pulling teams and rosters from start.gg…');
  try {
    const r = await fetch('http://localhost:3000/api/startgg/event-seeding', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ eventSlug: _seedEvent.eventSlug }) });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || `start.gg returned HTTP ${r.status}`);
    const entrants = data.entrants || [];
    if (!entrants.length) throw new Error('No entrants found for this event on start.gg — check the event URL.');
    // Preserve any ranks already entered (match by entrantId, then player gamertag).
    const prev = {}; _seedRows.forEach((r2) => { if (r2.entrantId) prev[r2.entrantId] = r2; });
    _seedRows = entrants.map((e) => {
      const old = prev[e.entrantId];
      const players = (e.players || []).map((p) => {
        const op = old && (old.players || []).find((x) => x.gamerTag === p.gamerTag);
        return { gamerTag: p.gamerTag, rank: op ? op.rank : '', rankValue: null,
          epic: p.epic || '', steam: p.steam || '', alts: p.alts || [],
          startggSlug: p.startggSlug || null, startggPlayerId: p.startggPlayerId || null };
      });
      return { entrantId: e.entrantId, name: e.name, seedNum: e.seedNum || null, players, leaguePts: null, perfScore: null };
    });
    const totalPlayers = _seedRows.reduce((s, r2) => s + (r2.players || []).length, 0);
    seedRecomputeValues();
    if (_seedLeagueId) seedApplyLeague(); else seedRender();
    seedStatus(`✓ Imported ${_seedRows.length} teams · ${totalPlayers} players from start.gg. Now import a rank CSV or enter ranks manually, then click ↑ Sort by Rank.`, 'ok');
  } catch (e) {
    seedStatus(`Pull failed — ${e.message || 'unknown error'}`, 'err');
    console.error('[seed-pull]', e);
  }
  finally { if (btn) { btn.disabled = false; btn.textContent = '↻ start.gg'; } }
}
function seedRenumber() { _seedRows.forEach((r, i) => { r.seedNum = i + 1; }); }
function seedOrderLabel() {
  const dir = ' (high→low)';
  const lbl = { rank: `Team rank · ${seedAggLabel()}${dir}`, league: `League points, then team rank${dir}`, seed: 'start.gg current seed', name: 'Team name (A→Z)' }[_seedSortKey] || 'Custom order (dragged)';
  const o = el('seed-orderby'); if (o) o.textContent = '— ordered by ' + lbl;
  document.querySelectorAll('.seed-sortbtn').forEach((b) => b.classList.toggle('is-on', b.dataset.sort === _seedSortKey));
}
// Build a profile URL from a stored value that may be a full URL OR a slug/username.
function teStartggLink(v) { v = (v || '').trim(); return /^https?:\/\//i.test(v) ? v : 'https://www.start.gg/' + v.replace(/^\/+/, ''); }
function teSixmansLink(v) { v = (v || '').trim(); return /^https?:\/\//i.test(v) ? v : 'https://www.rl6mans.com/profile/' + encodeURIComponent(v.toLowerCase()); }
function teTwitterLink(v) { v = (v || '').trim().replace(/^@/, ''); return /^https?:\/\//i.test(v) ? v : 'https://x.com/' + encodeURIComponent(v); }
function teTwitchLink(v)  { v = (v || '').trim(); return /^https?:\/\//i.test(v) ? v : 'https://twitch.tv/' + encodeURIComponent(v); }
function teInstaLink(v)   { v = (v || '').trim().replace(/^@/, ''); return /^https?:\/\//i.test(v) ? v : 'https://instagram.com/' + encodeURIComponent(v); }
function teTikTokLink(v)  { v = (v || '').trim().replace(/^@/, ''); return /^https?:\/\//i.test(v) ? v : 'https://tiktok.com/@' + encodeURIComponent(v); }
function teYouTubeLink(v) { v = (v || '').trim().replace(/^@/, ''); return /^https?:\/\//i.test(v) ? v : 'https://youtube.com/@' + encodeURIComponent(v); }

// Profile-link chips for a player (start.gg + 6mans). Accepts a gamertag string OR a
// player object. Prefers links STORED on the player; falls back to the auto-linked
// registry (state.playerProfiles, keyed by gamertag). Shown across seeding/team/match.
function playerProfileChips(p) {
  let tag = '', storedSgg = '', storedSix = '', storedSocials = {};
  if (typeof p === 'string') tag = p;
  else if (p) {
    tag = p.gamerTag || p.name || '';
    storedSgg = p.startgg || '';
    storedSix = p.sixmans || '';
    storedSocials = { twitter: p.twitter || '', twitch: p.twitch || '', discord: p.discord || '', instagram: p.instagram || '', tiktok: p.tiktok || '', youtube: p.youtube || '' };
  }
  const reg = (tag && currentState.playerProfiles) ? currentState.playerProfiles[tag.trim().toLowerCase()] : null;
  const chips = [];
  const sggUrl = storedSgg ? teStartggLink(storedSgg)
    : (reg && reg.startggSlug ? 'https://www.start.gg/' + String(reg.startggSlug).replace(/^\/+/, '') : '');
  if (sggUrl) chips.push(`<a class="pp-chip pp-sgg" href="${sggUrl}" target="_blank" title="start.gg profile"><img src="../assets/images/start.png" alt="start.gg"></a>`);
  let sixUrl = '', sixTitle = '6mans profile';
  if (storedSix) { sixUrl = teSixmansLink(storedSix); }
  else if (reg && reg.sixmans && reg.sixmans.name) {
    const s = reg.sixmans;
    sixUrl = 'https://www.rl6mans.com/profile/' + encodeURIComponent(String(s.name).toLowerCase());
    const meta = [s.rank, s.elo ? s.elo + ' ELO' : '', s.region].filter(Boolean).join(' · ');
    if (meta) sixTitle = '6mans · ' + meta;
  }
  if (sixUrl) chips.push(`<a class="pp-chip pp-6m" href="${sixUrl}" target="_blank" title="${tlEsc(sixTitle)}"><img src="../assets/images/sixmanlogo.webp" alt="6mans"></a>`);
  // Twitch — player-stored takes priority over registry
  const twitchVal = storedSocials.twitch || (reg && reg.twitch) || '';
  if (twitchVal) chips.push(`<a class="pp-chip pp-twitch" href="https://twitch.tv/${encodeURIComponent(twitchVal)}" target="_blank" title="Twitch: ${tlEsc(twitchVal)}"><svg viewBox="0 0 24 24" width="12" height="12"><path fill="currentColor" d="M11.571 4.714h1.715v5.143H11.57zm4.715 0H18v5.143h-1.714zM6 0L1.714 4.286v15.428h5.143V24l4.286-4.286h3.428L22.286 12V0zm14.571 11.143l-3.428 3.428h-3.429l-3 3v-3H6.857V1.714h13.714z"/></svg></a>`);
  // Twitter/X — player-stored takes priority over registry
  const twitterVal = storedSocials.twitter || (reg && reg.twitter) || '';
  if (twitterVal) chips.push(`<a class="pp-chip pp-twitter" href="https://x.com/${encodeURIComponent(twitterVal.replace(/^@/, ''))}" target="_blank" title="X/Twitter: ${tlEsc(twitterVal)}"><svg viewBox="0 0 24 24" width="12" height="12"><path fill="currentColor" d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-4.714-6.231-5.401 6.231H2.74l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg></a>`);
  // Player-stored-only socials
  if (storedSocials.discord) chips.push(`<span class="pp-chip pp-discord" title="Discord: ${tlEsc(storedSocials.discord)}">DC</span>`);
  if (storedSocials.instagram) chips.push(`<a class="pp-chip pp-instagram" href="https://instagram.com/${encodeURIComponent(storedSocials.instagram.replace(/^@/, ''))}" target="_blank" title="Instagram: ${tlEsc(storedSocials.instagram)}">IG</a>`);
  if (storedSocials.tiktok) chips.push(`<a class="pp-chip pp-tiktok" href="https://tiktok.com/@${encodeURIComponent(storedSocials.tiktok.replace(/^@/, ''))}" target="_blank" title="TikTok: ${tlEsc(storedSocials.tiktok)}">TK</a>`);
  if (storedSocials.youtube) chips.push(`<a class="pp-chip pp-youtube" href="https://youtube.com/@${encodeURIComponent(storedSocials.youtube.replace(/^@/, ''))}" target="_blank" title="YouTube: ${tlEsc(storedSocials.youtube)}">YT</a>`);
  if (reg && reg.countryCode) chips.push(`<span class="pp-chip pp-flag" title="${tlEsc(reg.country || reg.countryCode.toUpperCase())}"><img src="https://flagcdn.com/16x12/${reg.countryCode.toLowerCase()}.png" alt="${tlEsc(reg.countryCode.toUpperCase())}" width="16" height="12"></span>`);
  return chips.length ? `<span class="pp-chips">${chips.join('')}</span>` : '';
}

// Return 'flag' (B/B+), 'flag-high' (A/X), or null.  Only fires for rl-6mans mode.
const _RL6MANS_FLAG  = new Set(['b', 'b+']);
const _RL6MANS_FLAGX = new Set(['a', 'x']);
function seedRankAlertLevel(rank, modeKey) {
  if (modeKey !== 'rl-6mans') return null;
  const s = (rank || '').trim().toLowerCase();
  if (_RL6MANS_FLAGX.has(s)) return 'flag-high';
  if (_RL6MANS_FLAG.has(s))  return 'flag';
  return null;
}

function seedRender() {
  const list = el('seed-list'); if (!list) return;
  seedRenumber();
  seedOrderLabel();
  seedUpdateHeader();
  seedUpdateTabCounts();
  list.innerHTML = '';
  if (!_seedRows.length) { list.innerHTML = '<div class="seed-empty">No teams yet — Pull from Platform or Import a CSV.</div>'; return; }
  const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;');
  const mode = seedMode();
  // Typeahead datalist of tier names for tier-based games.
  let listId = '';
  if (mode.kind === 'tier' && mode.tiers) {
    listId = 'seed-tier-opts';
    let dl = document.getElementById(listId);
    if (!dl) { dl = document.createElement('datalist'); dl.id = listId; list.appendChild(dl); }
    const opts = mode.nodiv
      ? mode.tiers.slice()
      : mode.tiers.flatMap((t) => ['III', 'II', 'I'].map((d) => `${t} ${d}`));
    dl.innerHTML = opts.map((o) => `<option value="${esc(o)}">`).join('');
  }
  _seedRows.forEach((row, i) => {
    const card = document.createElement('div'); card.className = 'seed-team'; card.draggable = true; card.dataset.idx = i;
    const lpts = row.leaguePts != null ? `<span class="seed-lpts" title="League points (returning team)">${row.leaguePts} pts</span>` : '';
    const disp = seedTeamDisplay(row);
    const tvBadge = disp != null
      ? `<span class="seed-tv" title="Team seed value · ${esc(seedAggLabel())}">${esc(String(disp))}</span>`
      : `<span class="seed-tv seed-tv-empty" title="Add player ranks to compute">—</span>`;
    const perfBadge = row.perfScore != null
      ? `<span class="seed-perf-badge" title="start.gg tournament performance score (${row.perfScore}% — weighted recent placements)">${row.perfScore}%</span>`
      : '';
    const head = `<div class="seed-team-head"><span class="seed-grip" title="Drag to reorder">⠿</span><span class="seed-num">${i + 1}</span>`
      + `<div class="seed-team-name">${esc(row.name) || '(unnamed)'}</div>${lpts}${tvBadge}${perfBadge}</div>`;
    const players = (row.players || []).length
      ? (row.players || []).map((p, pi) => {
          const alert = seedRankAlertLevel(p.rank, _seedMode);
          const alertClass = alert ? ` seed-prank-${alert}` : '';
          const alertTitle = alert === 'flag-high' ? ' title="High-tier rank — double-check before finalising seeds"'
                           : alert === 'flag'      ? ' title="Mid-tier rank — verify before finalising seeds"'
                           : ' title="Player rank — sets this team\'s seed value"';
          return `<div class="seed-player"><span class="seed-ptag">${esc(p.gamerTag) || '(player)'}</span>${playerProfileChips(p.gamerTag)}`
            + `<input class="input-text seed-prank${alertClass}" data-pi="${pi}" value="${esc(p.rank)}" placeholder="${esc(mode.ph || 'rank')}"${listId ? ` list="${listId}"` : ''}${alertTitle}></div>`;
        }).join('')
      : '<div class="seed-noplayers">No players listed — Pull from Platform or add a player column to your CSV.</div>';
    card.innerHTML = head + `<div class="seed-players-wrap">${players}</div>`;
    card.querySelectorAll('.seed-prank').forEach((inp) => {
      inp.draggable = false;
      inp.addEventListener('mousedown', (e) => e.stopPropagation());
      inp.addEventListener('change', function () {
        const p = row.players[+this.dataset.pi]; if (!p) return;
        p.rank = this.value.trim(); p.rankValue = seedRankValue(p.rank, _seedMode);
        const disp2 = seedTeamDisplay(row); const badge = card.querySelector('.seed-tv');
        if (badge) { badge.textContent = disp2 != null ? String(disp2) : '—'; badge.classList.toggle('seed-tv-empty', disp2 == null); }
      });
    });
    card.addEventListener('dragstart', (e) => { if (e.target.classList && e.target.classList.contains('seed-prank')) { e.preventDefault(); return; } _seedDragIdx = i; card.classList.add('dragging'); });
    card.addEventListener('dragend', () => { _seedDragIdx = -1; card.classList.remove('dragging'); });
    card.addEventListener('dragover', (e) => { e.preventDefault(); card.classList.add('drag-over'); });
    card.addEventListener('dragleave', () => card.classList.remove('drag-over'));
    card.addEventListener('drop', (e) => {
      e.preventDefault(); card.classList.remove('drag-over');
      const from = _seedDragIdx, to = i;
      if (from < 0 || from === to) return;
      const moved = _seedRows.splice(from, 1)[0];
      _seedRows.splice(to, 0, moved);
      _seedSortKey = 'custom';
      seedRender();
    });
    list.appendChild(card);
  });
}
// Unified sort. key: rank | league | seed | name. 'rank'/'league' use the team aggregate value.
function seedSort(key) {
  _seedSortKey = key;
  // Safe descending comparator — unranked (null) always goes below ranked teams.
  // Using -Infinity causes NaN when both teams are null, producing indeterminate order.
  const cmpRank = (a, b) => {
    const av = seedTeamValue(a), bv = seedTeamValue(b);
    if (av === null && bv === null) return 0;
    if (av === null) return 1;
    if (bv === null) return -1;
    return bv - av;
  };
  if (key === 'name') _seedRows.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  else if (key === 'seed') _seedRows.sort((a, b) => (a.seedNum || 99999) - (b.seedNum || 99999));
  else if (key === 'league') _seedRows.sort((a, b) => {
    const ar = a.leaguePts != null, br = b.leaguePts != null;
    if (ar && br) return (b.leaguePts - a.leaguePts) || cmpRank(a, b);
    if (ar !== br) return ar ? -1 : 1;
    return cmpRank(a, b);
  });
  else _seedRows.sort(cmpRank);   // 'rank' — unranked teams always bottom
  seedRender();
  if (key !== 'league') seedStatus(`Ordered by ${({ rank: 'team rank', seed: 'start.gg seed', name: 'name' }[key] || key)}. Drag to fine-tune, then Save.`);
}
// Sort within each rank tier by tournament performance score (higher % = better placement history).
// Teams with the same 6mans tier but better start.gg results get seeded higher within that tier.
function seedSortByPerfScore() {
  const rv = (r) => { const v = seedTeamValue(r); return v == null ? -Infinity : v; };
  _seedRows.sort((a, b) => {
    const av = rv(a), bv = rv(b);
    if (av !== bv) return bv - av;                         // different tiers: keep tier order
    return (b.perfScore || 0) - (a.perfScore || 0);        // same tier: better perf score first
  });
  _seedSortKey = 'perf';
  seedRender();
  seedStatus('Sorted within rank tier by start.gg performance score. Drag to fine-tune, then Save.');
}

// Score teams from the local stats DB (Rocket Rush win/loss history). Instant, no API call.
async function seedFetchLocalScores() {
  const btn = el('seed-local-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Loading...'; }
  seedStatus('Loading Rocket Rush event history...');
  try {
    const res = await fetch('http://localhost:3000/api/seeding/local-scores', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ teams: _seedRows.map((r) => r.name) }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'Request failed');
    let scored = 0;
    _seedRows.forEach((row) => {
      const s = data.scores[row.name];
      row.perfScore = s != null ? s : null;
      if (s != null) scored++;
    });
    seedStatus(`Local history loaded: ${scored}/${_seedRows.length} teams scored from ${data.totalMatches || '?'} imported sets. Click "Sort in Tier" to apply.`, 'ok');
    seedRender();
  } catch (err) {
    seedStatus(`Local score failed: ${err.message}`, 'err');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Local'; }
  }
}

// Score teams by fetching each player's recent start.gg placements (all events, weighted by recency).
async function seedFetchPerformanceScores() {
  const btn = el('seed-score-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Fetching...'; }
  seedStatus('Fetching start.gg tournament history...');

  const allSlugs = [...new Set(
    _seedRows.flatMap((r) => (r.players || []).map((p) => p.startggSlug).filter(Boolean))
  )];

  if (!allSlugs.length) {
    seedStatus('No start.gg player profiles found. Pull entrants from start.gg first (Data → Pull).', 'err');
    if (btn) { btn.disabled = false; btn.textContent = 'start.gg'; }
    return;
  }

  try {
    const res = await fetch('http://localhost:3000/api/startgg/player-standings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ slugs: allSlugs }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'Request failed');

    _seedRows.forEach((row) => {
      const ps = (row.players || [])
        .map((p) => (p.startggSlug && data.scores[p.startggSlug] != null) ? data.scores[p.startggSlug] : null)
        .filter((s) => s !== null);
      row.perfScore = ps.length ? Math.round(ps.reduce((a, b) => a + b, 0) / ps.length * 10) / 10 : null;
    });

    const scored = _seedRows.filter((r) => r.perfScore != null).length;
    seedStatus(`start.gg scores loaded for ${scored}/${_seedRows.length} teams (${allSlugs.length} players). Click "Sort in Tier" to apply.`, 'ok');
    seedRender();
  } catch (err) {
    seedStatus(`Score fetch failed: ${err.message}`, 'err');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'start.gg'; }
  }
}

function seedCopyList() {
  const text = _seedRows.map((r, i) => `${i + 1}. ${r.name}`).join('\n');
  if (navigator.clipboard) navigator.clipboard.writeText(text);
  seedStatus('Copied the ordered seed list to clipboard.', 'ok');
}
function seedSave() {
  if (!_seedEvent) return;
  const entrants = _seedRows.map((r) => ({
    entrantId: r.entrantId || '', name: r.name || '', seedNum: r.seedNum || null,
    players: (r.players || []).map((p) => ({
      gamerTag: p.gamerTag || '', rank: p.rank || '',
      epic: p.epic || '', steam: p.steam || '', alts: Array.isArray(p.alts) ? p.alts : [],
      startggSlug: p.startggSlug || null, startggPlayerId: p.startggPlayerId || null,
    })),
  }));
  send('set_event_seeding', { id: _seedEvent.id, source: _seedEvent.seeding?.source || 'startgg', rankMode: _seedMode, agg: _seedAgg, entrants });
  seedStatus(`Saved · ${entrants.length} teams · ${seedMode().label} · ${seedAggLabel()}.`, 'ok');
}
async function seedPushStartgg() {
  if (!_seedEvent) return;
  if (!_seedEvent.eventSlug) { seedStatus('No start.gg event linked — activate the event first.', 'err'); return; }
  if (!currentState.startgg?.hasToken) { seedStatus('Add a start.gg TO/admin API token in Settings → Integrations to push seeds.', 'err'); return; }
  const order = _seedRows.map((r) => r.entrantId).filter(Boolean);
  const withoutId = _seedRows.filter((r) => !r.entrantId).length;
  if (!order.length) { seedStatus('No start.gg entrant IDs found — pull the roster from start.gg first, then import CSV ranks.', 'err'); return; }
  if (withoutId > 0) seedStatus(`Note: ${withoutId} CSV-only team(s) have no start.gg ID and will be skipped.`);
  if (!await appConfirm(`Push seed order for ${order.length} team${order.length !== 1 ? 's' : ''} to start.gg?\n\nThis overwrites the current seeding on "${_seedEvent.name || _seedEvent.eventSlug}".`, 'Push to start.gg')) return;
  const btn = el('seed-push'); if (btn) { btn.disabled = true; btn.textContent = 'Pushing…'; }
  seedStatus(`Exporting ${order.length} seeds to start.gg…`);
  try {
    const r = await fetch('http://localhost:3000/api/startgg/push-seeding', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ eventSlug: _seedEvent.eventSlug, order }) });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || `start.gg returned HTTP ${r.status}`);
    if (data.pushed < data.total) throw new Error(`Partial export: only ${data.pushed}/${data.total} seeds saved on "${data.phase}". Check your TO token permissions.`);
    seedSave();
    seedStatus(`✓ Exported ${data.pushed}/${data.total} seeds to start.gg phase "${data.phase}" — seeding saved locally.`, 'ok');
  } catch (e) {
    const msg = e.message || 'Export failed';
    seedStatus(`Export failed — ${msg}`, 'err');
    console.error('[push-seeding]', e);
  }
  finally { if (btn) { btn.disabled = false; btn.textContent = 'Push to start.gg'; } }
}
// Strip common tag decorations for fuzzy matching:
// "G2 | Jstn." → "jstn.",  "Player#1234" → "player"
function normTag(s) {
  return (s || '').toString()
    .replace(/^[^|#]*[|]\s*/, '')    // strip "Team | " prefix
    .replace(/\s*[#]\w+$/, '')        // strip "#1234" suffix
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

// Show the CSV column-mapping modal. Parses headers, pre-fills from saved event mapping or
// auto-detection, then waits for seedCsvConfirm() before running the actual import.
function seedImportCsv(text) {
  const rows = csvParse(text);
  if (!rows.length) { seedStatus('Empty or unreadable CSV.', 'err'); return; }
  _pendingCsvRows = rows;

  const rawHeaders = rows[0].map((h, i) => ({ label: (h || '').toString().trim() || `Col ${i + 1}`, idx: i }));
  const hdr = rawHeaders.map((h) => h.label.toLowerCase());
  const findCol = (...keys) => hdr.findIndex((h) => keys.some((k) => h.includes(k)));

  // Auto-detect — 'id' intentionally excluded (too broad, matches numeric ID columns)
  const autoTeam  = findCol('team', 'entrant', 'squad', 'org', 'group');
  const autoGamer = findCol('gamertag', 'gamer tag', 'gamer_tag', 'player', 'tag',
                             'username', 'handle', 'discord', 'epic', 'steam', 'rocket', 'rl');
  const autoRank  = findCol('rank', 'mmr', 'elo', 'rating', 'mr', 'tier', 'division', 'score', 'pts', 'point');

  // Load saved mapping keyed by event ID/slug
  const mapKey = `ne_seed_csv_map_${(_seedEvent && (_seedEvent.id || _seedEvent.slug)) || 'global'}`;
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem(mapKey) || '{}'); } catch { /* */ }

  const teamSel  = el('seed-csv-col-team');
  const gamerSel = el('seed-csv-col-gamer');
  const rankSel  = el('seed-csv-col-rank');
  if (!gamerSel || !rankSel) return;

  const buildOptions = (sel, preferred) => {
    sel.innerHTML = '<option value="-1">— not in CSV / skip —</option>';
    rawHeaders.forEach((h) => {
      const opt = document.createElement('option');
      opt.value = h.idx;
      const sample = rows.length > 1 ? (rows[1][h.idx] || '').toString().trim() : '';
      opt.textContent = `${h.label}${sample ? `  —  e.g. "${sample}"` : ''}`;
      sel.appendChild(opt);
    });
    sel.value = preferred >= 0 ? preferred : -1;
  };

  if (teamSel) buildOptions(teamSel,  saved.team  != null ? saved.team  : autoTeam);
  buildOptions(gamerSel, saved.gamer != null ? saved.gamer : autoGamer);
  buildOptions(rankSel,  saved.rank  != null ? saved.rank  : autoRank);

  // Wire live preview to all three selects and run once immediately.
  [teamSel, gamerSel, rankSel].forEach((sel) => {
    if (!sel) return;
    sel.removeEventListener('change', seedCsvPreview);
    sel.addEventListener('change', seedCsvPreview);
  });

  el('seed-csv-modal')?.removeAttribute('hidden');
  seedCsvPreview();
}

// Render a live match preview inside the modal.
// Scans the full CSV, collects all matches, then samples 4 spread across the list so the
// preview shows a variety of players — not always the same first row.
function seedCsvPreview() {
  const esc = escHtml;
  const previewEl = el('seed-csv-preview');
  if (!previewEl || !_pendingCsvRows || _pendingCsvRows.length < 2) {
    if (previewEl) previewEl.className = 'seed-csv-prev-idle';
    return;
  }

  const teamCol  = parseInt(el('seed-csv-col-team')?.value  ?? '-1');
  const gamerCol = parseInt(el('seed-csv-col-gamer')?.value ?? '-1');
  const rankCol  = parseInt(el('seed-csv-col-rank')?.value  ?? '-1');
  const rows = _pendingCsvRows;

  // BUILD mode — no start.gg roster; echo what the column selections pick up from rows 2–4.
  if (_seedRows.length === 0) {
    const samples = rows.slice(1, 4).map((r, ri) => {
      const parts = [
        teamCol  >= 0 ? esc((r[teamCol]  || '').toString().trim()) : null,
        gamerCol >= 0 ? `<b>${esc((r[gamerCol] || '').toString().trim())}</b>` : null,
        rankCol  >= 0 ? esc((r[rankCol]  || '').toString().trim()) : null,
      ].filter(Boolean);
      return parts.length ? `<div class="seed-csv-prev-entry-build">Row ${ri + 2}: ${parts.join(' · ')}</div>` : null;
    }).filter(Boolean);
    previewEl.className = 'seed-csv-prev-idle';
    previewEl.innerHTML = samples.length ? samples.join('') : 'Select at least one column to preview.';
    return;
  }

  // MERGE mode — build lookup (same logic as seedExecuteCsvImport).
  const byGamer = new Map();
  const byTeamGamer = new Map();
  _seedRows.forEach((sggRow) => {
    const normTeam = sggRow.name.toLowerCase().replace(/[^a-z0-9]/g, '');
    (sggRow.players || []).forEach((p) => {
      if (!p.gamerTag) return;
      const raw  = p.gamerTag.toLowerCase().trim();
      const norm = normTag(p.gamerTag);
      const bare = raw.replace(/[^a-z0-9]/g, '');
      byGamer.set(raw,  { player: p, team: sggRow });
      if (norm !== raw) byGamer.set(norm, { player: p, team: sggRow });
      if (bare && bare !== norm) byGamer.set(bare, { player: p, team: sggRow });
      byTeamGamer.set(`${normTeam}|${norm}`, { player: p, team: sggRow });
      if (bare) byTeamGamer.set(`${normTeam}|${bare}`, { player: p, team: sggRow });
    });
  });

  // Scan all rows, collect every match.
  const allMatches = [];
  let firstUnmatched = null;
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const rawGamer = (gamerCol >= 0 ? r[gamerCol] : r[0] || '').toString().trim();
    const rawTeam  = teamCol >= 0 ? (r[teamCol] || '').toString().trim() : '';
    const rank     = rankCol >= 0 ? (r[rankCol] || '').toString().trim() : '';
    if (!rawGamer) continue;
    let result = null;
    if (rawTeam) {
      const nt = rawTeam.toLowerCase().replace(/[^a-z0-9]/g, '');
      result = byTeamGamer.get(`${nt}|${normTag(rawGamer)}`)
            || byTeamGamer.get(`${nt}|${rawGamer.toLowerCase().replace(/[^a-z0-9]/g, '')}`);
    }
    result = result || byGamer.get(rawGamer.toLowerCase()) || byGamer.get(normTag(rawGamer))
                    || byGamer.get(rawGamer.toLowerCase().replace(/[^a-z0-9]/g, ''));
    if (result) {
      allMatches.push({ result, csv: { rawGamer, rawTeam, rank }, rowIdx: i + 1 });
    } else if (!firstUnmatched) {
      firstUnmatched = { rawGamer, rawTeam, rank };
    }
  }

  if (allMatches.length === 0) {
    // No matches at all — show a comparison so the user understands the mismatch.
    const sggSample = _seedRows.flatMap((r) => (r.players || []).map((p) => p.gamerTag)).slice(0, 3).join(', ');
    previewEl.className = 'seed-csv-prev seed-csv-prev-warn';
    previewEl.innerHTML = `
      <span class="seed-csv-prev-lbl">✗ No matches — check column selection</span>
      <div class="seed-csv-prev-rows">
        <div class="seed-csv-prev-row" style="grid-template-columns:68px 1fr">
          <span class="seed-csv-prev-field">CSV has</span>
          <span class="seed-csv-prev-val">${firstUnmatched ? esc(firstUnmatched.rawGamer) : '—'}</span>
        </div>
        <div class="seed-csv-prev-row" style="grid-template-columns:68px 1fr">
          <span class="seed-csv-prev-field">start.gg</span>
          <span class="seed-csv-prev-sgg" style="opacity:.6">${esc(sggSample)}…</span>
        </div>
      </div>`;
    return;
  }

  // Sample up to 4 matches spread evenly across the full match list for variety.
  const n = allMatches.length;
  const idxs = n <= 4
    ? allMatches.map((_, i) => i)
    : [0, Math.floor(n * 0.33), Math.floor(n * 0.66), n - 1];
  const samples = [...new Set(idxs)].map((i) => allMatches[i]);
  const unmatched = rows.slice(1).filter((r) => r.some((x) => (x || '').toString().trim())).length - allMatches.length;

  // Render samples as an aligned table so all columns line up across rows.
  const isNoRank = (r) => !r || r.trim() === '' || r.trim().toUpperCase() === 'NA';

  const rowHtml = samples.map(({ result, csv, rowIdx }) => {
    // Gamertag cell: show CSV value dimmed → start.gg value green; omit arrow if identical.
    const csvGamer = esc(csv.rawGamer);
    const sggGamer = esc(result.player.gamerTag);
    const gamerCell = csv.rawGamer.toLowerCase() === result.player.gamerTag.toLowerCase()
      ? `<span class="pcell-sgg">${sggGamer}</span>`
      : `<span class="pcell-csv">${csvGamer}</span><span class="pcell-arr">→</span><span class="pcell-sgg">${sggGamer}</span>`;

    // Team cell: use CSV team col value; fall back to "TEAM | Player" prefix from gamertag.
    let csvTeam = csv.rawTeam;
    if (!csvTeam && csv.rawGamer.includes('|')) csvTeam = csv.rawGamer.split('|')[0].trim();
    const sggTeam = esc(result.team.name);
    const teamCell = csvTeam
      ? `<span class="pcell-csv">${esc(csvTeam)}</span><span class="pcell-arr">→</span><span class="pcell-sgg">${sggTeam}</span>`
      : `<span class="pcell-sgg">${sggTeam}</span>`;

    // Rank cell: blank/NA players were admin-accepted without registering a rank — show dash.
    const rankCell = isNoRank(csv.rank)
      ? `<span class="pcell-rank-none">—</span>`
      : `<span class="pcell-rank-badge">${esc(csv.rank.trim())}</span>`;

    return `<tr>
      <td class="pcol-row">${rowIdx}</td>
      <td class="pcol-gamer">${gamerCell}</td>
      <td class="pcol-team">${teamCell}</td>
      <td class="pcol-rank">${rankCell}</td>
    </tr>`;
  }).join('');

  const unmatchedNote = unmatched > 0
    ? `<div class="seed-csv-prev-unmatched">${unmatched} row${unmatched !== 1 ? 's' : ''} not matched — columns may differ for those players</div>`
    : '';

  previewEl.className = 'seed-csv-prev seed-csv-prev-ok';
  previewEl.innerHTML = `
    <span class="seed-csv-prev-lbl">✓ ${allMatches.length} match${allMatches.length !== 1 ? 'es' : ''} — ${samples.length} shown</span>
    <table class="seed-csv-prev-table">
      <thead><tr>
        <th class="pcol-row">#</th>
        <th class="pcol-gamer">Gamertag</th>
        <th class="pcol-team">Team</th>
        <th class="pcol-rank">Rank</th>
      </tr></thead>
      <tbody>${rowHtml}</tbody>
    </table>
    ${unmatchedNote}`;
}

// Called by the mapping modal's Import button.
function seedCsvConfirm() {
  const rows = _pendingCsvRows;
  if (!rows) return;
  _pendingCsvRows = null;

  const teamCol  = parseInt(el('seed-csv-col-team')?.value  ?? '-1');
  const gamerCol = parseInt(el('seed-csv-col-gamer')?.value ?? '-1');
  const rankCol  = parseInt(el('seed-csv-col-rank')?.value  ?? '-1');

  if (el('seed-csv-remember')?.checked !== false) {
    const mapKey = `ne_seed_csv_map_${(_seedEvent && (_seedEvent.id || _seedEvent.slug)) || 'global'}`;
    localStorage.setItem(mapKey, JSON.stringify({ team: teamCol, gamer: gamerCol, rank: rankCol }));
  }

  el('seed-csv-modal')?.setAttribute('hidden', '');
  seedExecuteCsvImport(rows, teamCol, gamerCol, rankCol);
}

// Core CSV import — runs after column mapping is confirmed.
// teamCol: CSV column index for the team/squad name (-1 = not provided)
function seedExecuteCsvImport(rows, teamCol, gamerCol, rankCol) {
  // ── MERGE MODE: roster already loaded from start.gg ─────────────────────
  if (_seedRows.length > 0) {
    if (rankCol < 0) { seedStatus('No rank column selected — re-import and pick one.', 'err'); return; }

    // byGamer: gamerTag → player (fuzzy fallback)
    const byGamer = new Map();
    // byTeamGamer: "normTeam|normGamer" → player (precise match when team col is set)
    const byTeamGamer = new Map();
    _seedRows.forEach((row) => {
      const normTeam = row.name.toLowerCase().replace(/[^a-z0-9]/g, '');
      (row.players || []).forEach((p) => {
        if (!p.gamerTag) return;
        const raw  = p.gamerTag.toLowerCase().trim();
        const norm = normTag(p.gamerTag);
        const bare = raw.replace(/[^a-z0-9]/g, '');
        byGamer.set(raw, p);
        if (norm !== raw) byGamer.set(norm, p);
        if (bare && bare !== norm && bare !== raw) byGamer.set(bare, p);
        // precise team+gamer key
        byTeamGamer.set(`${normTeam}|${norm}`, p);
        if (bare) byTeamGamer.set(`${normTeam}|${bare}`, p);
      });
    });

    let matched = 0;
    const notFound = [];
    rows.slice(1).forEach((r) => {
      const rawGamer = (gamerCol >= 0 ? r[gamerCol] : r[0] || '').toString().trim();
      const rank     = rankCol >= 0 ? (r[rankCol] || '').toString().trim() : '';
      if (!rawGamer) return;

      let p;
      // If team col is mapped, try precise team+gamer match first to avoid cross-team collisions.
      if (teamCol >= 0) {
        const rawTeam  = (r[teamCol] || '').toString().trim();
        const normTeam = rawTeam.toLowerCase().replace(/[^a-z0-9]/g, '');
        const normGamer = normTag(rawGamer);
        const bareGamer = rawGamer.toLowerCase().replace(/[^a-z0-9]/g, '');
        p = byTeamGamer.get(`${normTeam}|${normGamer}`) || byTeamGamer.get(`${normTeam}|${bareGamer}`);
      }
      // Fall back to gamer-only fuzzy lookup
      p = p || byGamer.get(rawGamer.toLowerCase())
            || byGamer.get(normTag(rawGamer))
            || byGamer.get(rawGamer.toLowerCase().replace(/[^a-z0-9]/g, ''));

      if (p) {
        // Skip rank update for admin-accepted players who bypassed registration (blank or NA rank).
        if (rank && rank.toUpperCase() !== 'NA') {
          p.rank = rank; p.rankValue = seedRankValue(rank, _seedMode);
        }
        matched++;
      } else notFound.push(rawGamer);
    });
    seedRecomputeValues();
    seedSort('rank');

    if (notFound.length) {
      const csvSample = notFound.slice(0, 4).join(', ');
      const sggSample = _seedRows.flatMap((r) => (r.players || []).map((p) => p.gamerTag)).slice(0, 3).join(', ');
      const all = matched === 0;
      const warn = all
        ? `All ${notFound.length} unmatched — wrong column? CSV: ${csvSample}. start.gg: ${sggSample}…`
        : `${notFound.length} not matched. CSV: ${csvSample}. start.gg: ${sggSample}…`;
      seedStatus(`${matched} rank${matched !== 1 ? 's' : ''} updated · ${warn}`, all ? 'err' : '');
    } else {
      seedStatus(`✓ CSV merged — all ${matched} player ranks updated. Sorted by avg team rank.`, 'ok');
    }
    return;
  }

  // ── BUILD MODE: no roster yet — construct teams from CSV ─────────────────
  const hdr = rows[0].map((h) => (h || '').toString().trim().toLowerCase());
  const findHdr = (...keys) => hdr.findIndex((h) => keys.some((k) => h.includes(k)));
  // In BUILD mode, team col from the mapper takes priority; fall back to auto-detect.
  const buildTeamCol = teamCol >= 0 ? teamCol : findHdr('team', 'entrant', 'squad', 'org');
  const nameCol = buildTeamCol >= 0 ? buildTeamCol : (gamerCol >= 0 ? gamerCol : 0);
  const byTeam  = new Map();
  let players = 0;
  rows.slice(1).forEach((r) => {
    const teamName = (r[nameCol] || '').toString().trim();
    if (!teamName) return;
    const gamer = gamerCol >= 0 ? (r[gamerCol] || '').toString().trim() : '';
    const rank  = rankCol  >= 0 ? (r[rankCol]  || '').toString().trim() : '';
    const key   = teamName.toLowerCase();
    if (!byTeam.has(key)) byTeam.set(key, { entrantId: '', name: teamName, seedNum: null, players: [], leaguePts: null });
    const t = byTeam.get(key);
    if (gamer && gamer.toLowerCase() !== key) { t.players.push({ gamerTag: gamer, rank, rankValue: null }); players++; }
    else if (rank && !t.players.length) { t.players.push({ gamerTag: teamName, rank, rankValue: null }); players++; }
  });
  _seedRows = [...byTeam.values()];
  seedRecomputeValues();
  seedSort('rank');
  seedStatus(`Built ${_seedRows.length} teams · ${players} players from CSV${rankCol >= 0 ? ' · sorted by avg team rank.' : '.'}`, rankCol >= 0 ? 'ok' : 'err');
}
function csvParse(text) {
  const out = []; let row = [], cell = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); out.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if (cell.length || row.length) { row.push(cell); out.push(row); }
  return out.filter((r) => r.some((x) => (x || '').toString().trim()));
}
