        const gear = chip.querySelector('.qk-chip-gear');
        if (gear) gear.addEventListener('click', (e) => { e.stopPropagation(); if (typeof bbOpenTriggerConfig === 'function') bbOpenTriggerConfig(item.trig, chip); });
