  if (pwEl) pwEl.value = '';
  btn.dataset.clearing = '1';
  send('set_obs_settings', getObsPayload());
  delete btn.dataset.clearing;
  btn.style.display = 'none';
  el('obs-password-indicator').style.display = 'none';
  const pwInd = el('obs-password-indicator');
